STAGE_WEIGHTS = {"kalshi": 0.5, "fair": 0.25, "flow": 0.25}


def stage_blend(kalshi_yes, fair_yes, flow_up):
    """(p_yes, parts) - the weighted chance of UP from whichever of the three reads exist right now."""
    parts = {"kalshi": kalshi_yes, "fair": fair_yes, "flow": flow_up}
    used = {k: v for k, v in parts.items() if v is not None}
    if not used:
        return None, parts
    wsum = sum(STAGE_WEIGHTS[k] for k in used)
    return sum(STAGE_WEIGHTS[k] * v for k, v in used.items()) / wsum, parts


