def round_line_stats(symbol, line, open_ts, end_ts=None):
    """Price vs the line for one round, from the live blended tick tape: how many times it crossed (and which way), the
    path in 5-second steps as % above / below the line, and the round's high / low. A cross only counts once price is
    clearly on the other side (CROSS_BAND_PCT), so wiggling on the line is not counted again and again."""
    if not line or not open_ts:
        return None
    end_ts = end_ts or time.time()
    band = line * CROSS_BAND_PCT
    side = 0                       # the side as last COUNTED
    last_cross = -1e9
    crosses = ups = downs = 0
    events, path = [], []
    hi = lo = None
    last_b = None
    for t, px in get_tick_history(symbol):
        if t < open_ts or t > end_ts:
            continue
        hi = px if hi is None else max(hi, px)
        lo = px if lo is None else min(lo, px)
        d = px - line
        sd = 1 if d > band else (-1 if d < -band else 0)
        if sd:
            if not side:
                side = sd
            elif sd != side and (t - last_cross) >= CROSS_MIN_GAP_S:
                crosses += 1
                if sd > 0:
                    ups += 1
                else:
                    downs += 1
                events.append((int(t - open_ts), sd))
                side = sd
                last_cross = t
        b = int((t - open_ts) // 5)
        if b != last_b:
            path.append([int(t - open_ts), round(d / line * 100, 4)])
            last_b = b
        else:
            path[-1] = [int(t - open_ts), round(d / line * 100, 4)]
    return {"crosses": crosses, "up": ups, "down": downs, "events": events, "path": path, "hi": hi, "lo": lo,
            "range_pct": ((hi - lo) / line) if hi is not None else None, "side": side}


# ---- sit-out rules + late call (2026-10-20, user request) ----
SITOUT_COINFLIP = 0.03        # sit out ONLY when the call's chance is within 3 points of 50/50
SITOUT_CROSSES = 4            # 4+ line crosses at the mark = the line is being fought over -> sit this one out
SITOUT_LATE_CROSSES = 2       # or 2+ crosses after the 5:00 mark (still flipping deep into the round)
SITOUT_PACE = 0.5             # volume under half its normal pace ...
SITOUT_DIST_PCT = 0.0002      # ... with price within 0.02% of the line = no real move to read
LATE_MIN_SURE = 0.80          # a skipped round gets a LATE CALL once BRAIN is this sure ...
LATE_MIN_DIST_PCT = 0.0004    # ... price is 0.04%+ clear of the line ...
