def _coin_amt(asset, q):
    return f"{q:,.2f}" if asset == "BTC" else f"{q:,.0f}"


def _rsi_gauge_svg(rsi1, rsi5):
    """Semicircle 0..100 RSI dial: cyan oversold (<=30), grey middle, magenta overbought (>=70). Needle = 1-minute RSI,
    small triangle on the rim = 5-minute RSI."""
    cx, cy, r = 90, 90, 70

    def xy(v, rad):
        a = math.radians(180 - v / 100 * 180)
        return cx + rad * math.cos(a), cy - rad * math.sin(a)
    arcs = []
    for z0, z1, col in ((0, 30, "#00e5ff"), (30, 70, "#4a3c43"), (70, 100, "#ff4f7e")):
        x1, y1 = xy(z0, r); x2, y2 = xy(z1, r)
        arcs.append(f'<path d="M {x1:.1f} {y1:.1f} A {r} {r} 0 0 1 {x2:.1f} {y2:.1f}" stroke="{col}" stroke-width="14" fill="none"/>')
    for t in (30, 50, 70):
        a1, b1 = xy(t, r - 9); a2, b2 = xy(t, r + 9)
        arcs.append(f'<line x1="{a1:.1f}" y1="{b1:.1f}" x2="{a2:.1f}" y2="{b2:.1f}" stroke="#211b1e" stroke-width="2"/>')
    out = "".join(arcs)
    if rsi5 is not None:
        tx, ty = xy(max(0, min(100, rsi5)), r + 13)
        out += f'<circle cx="{tx:.1f}" cy="{ty:.1f}" r="5" fill="#e5b85c" stroke="#211b1e" stroke-width="1.5"><title>5-minute RSI {rsi5:.0f}</title></circle>'
    if rsi1 is not None:
        nx, ny = xy(max(0, min(100, rsi1)), r - 12)
        out += (f'<line x1="{cx}" y1="{cy}" x2="{nx:.1f}" y2="{ny:.1f}" stroke="#fbf4ec" stroke-width="3" stroke-linecap="round"/>'
                f'<circle cx="{cx}" cy="{cy}" r="5" fill="#fbf4ec"/>'
                f'<text x="{cx}" y="{cy + 26}" text-anchor="middle" fill="#fbf4ec" font-size="18" font-weight="800">{rsi1:.0f}</text>')
    else:
        out += f'<text x="{cx}" y="{cy + 20}" text-anchor="middle" fill="#bcaaa1" font-size="12">warming up</text>'
    for t, col in ((30, "#00e5ff"), (70, "#ff4f7e")):
        lx, ly = xy(t, r - 24)
        out += f'<text x="{lx:.1f}" y="{ly + 4:.1f}" text-anchor="middle" fill="{col}" font-size="11" font-weight="700">{t}</text>'
    return f'<svg viewBox="0 0 180 122" width="150" height="102" style="display:block;">{out}</svg>'


def rsi_flip_risk(name, d):
    """Flip-risk score 0-100 and the way a flip would go, from: how deep the 1-minute RSI is into overbought / oversold,
    whether the 5-minute RSI agrees, whether the RSI is already turning back, a price-vs-volume-delta DIVERGENCE over the
    last 10 minutes (price up but sellers were the aggressors = buying is not backing the move), and a fresh liquidity
    sweep of the high / low in the same direction. Watch-only."""
    rm = d.get("rsi_multi") or {}
    r1, r5, rp, chg = rm.get("rsi1"), rm.get("rsi5"), rm.get("rsi1_prev"), rm.get("chg10_pct")
    if r1 is None:
        return None
    hot = r1 >= 50
    direction = "DOWN" if hot else "UP"
    ext = lambda v: max(0.0, min(1.0, ((v - 60) if hot else (40 - v)) / 25.0)) if v is not None else 0.0
    reasons = []
    score = 55 * ext(r1)
    if r1 >= 70:
        reasons.append(f"1-min RSI {r1:.0f} overbought")
    elif r1 <= 30:
        reasons.append(f"1-min RSI {r1:.0f} oversold")
    if r5 is not None and ext(r5) > 0:
        score += 15 * ext(r5)
        if (hot and r5 >= 70) or (not hot and r5 <= 30):
            reasons.append(f"5-min RSI {r5:.0f} agrees")
    if rp is not None and ext(r1) > 0 and ((hot and rp > r1 + 2) or (not hot and rp < r1 - 2)):
        score += 12
        reasons.append("RSI already turning back")
    try:
        w = _flow.HUB.window_detail(name, 600)
        tot = w["buy"] + w["sell"]
        net = (w["buy"] - w["sell"]) / tot if tot > 0 else 0.0
    except Exception:
        net = 0.0
    if chg is not None and ext(r1) > 0:
        if hot and chg > 0 and net <= -0.02:
            score += 18
            reasons.append("bearish divergence: price up 10m but sellers were the aggressors")
        elif (not hot) and chg < 0 and net >= 0.02:
            score += 18
            reasons.append("bullish divergence: price down 10m but buyers were the aggressors")
    want = "sell" if hot else "buy"
    if _ENG.recent_kind(name, ("stoprun",), side=want, within=240):
        score += 15
        reasons.append(f"a fake breakout {'above the high' if hot else 'below the low'} just failed")
    score = max(0.0, min(100.0, score))
    level = "LOW" if score < 25 else ("WATCH" if score < 50 else ("HIGH" if score < 75 else "EXTREME"))
    return {"score": score, "level": level, "direction": direction, "reasons": reasons, "r1": r1, "r5": r5, "net10": net, "chg10": chg}


def build_rsi_flip_widget(name, d):
    rm = d.get("rsi_multi") or {}
    fr = rsi_flip_risk(name, d)
    r1, r5 = rm.get("rsi1"), rm.get("rsi5")
    if r1 is None:
        zone, zcls = "warming up (needs about 20 minutes of history)", "flat"
    elif r1 >= 75:
        zone, zcls = "OVERBOUGHT - WARNING", "rsi-hot rsi-hot-over"
    elif r1 >= 70:
        zone, zcls = "overbought", "rsi-over"
    elif r1 <= 25:
        zone, zcls = "OVERSOLD - WARNING", "rsi-hot rsi-hot-under"
    elif r1 <= 30:
        zone, zcls = "oversold", "rsi-under"
    else:
        zone, zcls = "neutral", "flat"
    if fr:
        lv = fr["level"]
        lcls = {"LOW": "flat", "WATCH": "warn", "HIGH": "fr-high", "EXTREME": "fr-ext"}[lv]
        arrow = "<i class=va-d></i>" if fr["direction"] == "DOWN" else "<i class=va-u></i>"
        way = (f'<span class="{"down" if fr["direction"] == "DOWN" else "up"}">{arrow} could flip {fr["direction"]}</span>'
               if lv != "LOW" else '<span class="hint">nothing stretched</span>')
        bar = (f'<div class="fr-track"><i class="{lcls}" style="width:{max(fr["score"], 2):.0f}%"></i></div>'
               f'<div class="fr-line"><span class="{lcls}"><b>FLIP RISK {lv}</b> {fr["score"]:.0f}/100</span> {way}</div>')
        why = ("<br>".join(fr["reasons"])) if fr["reasons"] else "RSI is in the middle - not overbought or oversold."
        bar += f'<div class="fr-why hint">{why}</div>'
    else:
        bar = '<div class="fr-line hint">flip risk: warming up</div>'
    return (f'<div class="top-w top-rsi"><div class="top-w-title">RSI FLIP METER</div>'
            f'<div class="top-rsi-body">{_rsi_gauge_svg(r1, r5)}<div class="top-rsi-txt">'
            f'<div class="{zcls}" style="font-weight:800;font-size:14px;">{zone.upper() if r1 is not None and (r1 >= 70 or r1 <= 30) else zone}</div>'
            f'<div class="hint">1-min RSI <b>{"%.0f" % r1 if r1 is not None else "--"}</b> &middot; 5-min RSI <b>{"%.0f" % r5 if r5 is not None else "--"}</b> '
            f'<span title="gold dot on the dial">(&#9679; = 5-min)</span></div>{bar}</div></div>'
            f'<div class="hint top-note">Watch only: an extreme RSI alone did NOT predict reversals in this project&#39;s 15-min back-test '
            f'(trends often run straight through 70 / 30). It means more when a divergence or a failed fake breakout shows up with it.</div></div>')


def _stage_ref(d):
    """(key, call) of the call the flip meter should protect: the sealed call once it exists, else the early call."""
    sc = d.get("stage_calls") or {}
    for k in ("sealed", "early"):
        c = sc.get(k) or {}
        if c.get("call"):
            return k, c["call"]
    return None, None


def build_flip_chance_widget(name, d):
    kp = d.get("kalshi_price")
    key, call = _stage_ref(d)
    label = {"sealed": "SEALED call", "early": "EARLY call"}.get(key)
    if call is None:
        call = d.get("locked_call")
        label = "bot's locked call" if call else None
    if kp is None:
        pct = None
    elif call == "YES":
        pct = (1 - kp) * 100
    elif call == "NO":
        pct = kp * 100
    else:
        pct = (1 - max(kp, 1 - kp)) * 100
    gauge = build_flip_gauge_svg(pct) if pct is not None else '<div class="hint">waiting for the market&#39;s price</div>'
    if call in ("YES", "NO"):
        other = "NO" if call == "YES" else "YES"
        cap = (f'Chance the {label} (<span class="{"up" if call == "YES" else "down"}">{"UP" if call == "YES" else "DOWN"}</span>) '
               f'flips to <span class="{"up" if other == "YES" else "down"}">{"UP" if other == "YES" else "DOWN"}</span> before the close')
    else:
        cap = "No call is locked yet, so this shows the chance that the market's current favorite flips."
    marker = ""
    if pct is not None:
        mkey = f'{name}::{d.get("ticker", "")}' + (f"::{key}" if key else "")
        marker = f'<span class="flip-chance-value" data-flip-chance-key="{mkey}" data-flip-chance-pct="{pct:.2f}" style="display:none;"></span>'
    return (f'<div class="top-w top-flip"><div class="top-w-title">FLIP METER <span class="hint">the market&#39;s own price</span></div>'
            f'<div class="flip-gauge">{gauge}</div><div class="flip-cap">{cap}</div>{marker}</div>')


def _ago(ts):
    s = max(0, int(time.time() - ts))
    return f"{s}s ago" if s < 90 else (f"{s // 60}m ago" if s < 3600 else f"{s // 3600}h ago")


def _alert_line(a, dec):
    """One short line per alert: what, how big, which exchange, what price. Everything else is in the hover / tap text."""
    sd = a["side"]
    usd = _usd_short(a["usd"]) if a.get("usd") else ""
    px = fmt_price(a["price"], dec) if a.get("price") else ""
    ven = a.get("venue") or ""
    bs = "BUY" if sd == "buy" else "SELL"
    k = a["kind"]
    where = " &middot; ".join(x for x in (ven, ("@ " + px) if px else "") if x)
    if k == "whale":
        return f"WHALE {bs} {usd}", where
    if k == "amass":
        return (a["title"].split(":")[0], f'{a.get("n_orders", "?")} big orders &middot; {a.get("n_venues", "?")} exchanges &middot; last 30 sec &middot; still counting')
    if k == "choke":
        return ("ORDER FLOOD &ndash; BLOW-OFF", a["title"].split("BLOW-OFF ")[-1].lower() + " &middot; " + ("mostly buyers" if sd == "buy" else "mostly sellers")
                + " &middot; rushes this crowded often exhaust and snap back")
    if k == "mempool":
        return (a["title"].split(":")[0], a["title"].split(": ", 1)[-1].lower() + " &middot; " + (a.get("detail") or "").split(";")[-1].split(".")[0].strip())
    if k == "burst":
        b_, s_ = a.get("buy_usd"), a.get("sell_usd")
        net_side = "BUYERS" if sd == "buy" else "SELLERS"
        return (f"{net_side} OUT-TRADED {'SELLERS' if sd == 'buy' else 'BUYERS'} BY {usd}",
                "last 10 sec, all exchanges" + (f" &middot; {_usd_short(s_)} sold vs {_usd_short(b_)} bought" if (b_ is not None and s_ is not None) else "")
                + " &middot; <i>total of all trades, not a new order</i>")
    if k == "sweep":
        return f"BIG {bs} {usd}", where + " &middot; moved the price"
    if k == "liq":
        return (f"FORCED SALE (longs wiped) {usd}" if sd == "sell" else f"FORCED BUY (shorts wiped) {usd}"), where
    if k == "absorbed":
        # 2026-10-22 (user): plain English - who ate whose big order
        return (f"BUYERS ATE A BIG SELL ORDER {usd}" if sd == "buy" else f"SELLERS ATE A BIG BUY ORDER {usd}"), where
    if k == "pulled":
        dist = (f" &middot; {fmt_price(a['dist_usd'], dec)} from price" if a.get("dist_usd") is not None else "")
        return f"FAKE {'SELL' if sd == 'buy' else 'BUY'} ORDER PULLED {usd}", ("was @ " + px if px else "") + dist + " &middot; never filled"
    if k == "moved":
        # a big resting order (a "wall") changed price. Say what it MEANS, not the jargon.
        fp = fmt_price(a["from_price"], dec) if a.get("from_price") else ""
        n = a.get("moves") or 1
        wall = (a.get("wall") or "").lower()
        up = (a.get("dir") or "").upper() == "UP"
        if wall.startswith("buy"):
            head = "BIG BUYER CHASING PRICE UP" if up else "BUYERS STEPPED BACK (less support)"
        else:
            head = "SELLERS STEPPED BACK (more room up)" if up else "BIG SELLER CHASING PRICE DOWN"
        return f"{head} {usd}", f"big order {fp} &rarr; {px}" + (f" &middot; {n}x" if n > 1 else "")
    if k == "wall":
        return f"BIG {'SELL' if sd == 'sell' else 'BUY'} ORDER WAITING {usd}", ("Index venue 1 @ " + px) if px else "Index venue 1"
    return a["title"], ""


def _alert_status_line(name, h):
    """Live strip under the title: exchanges feeding the alerts, the order-pace (blow-off) gauge, and the network jam."""
    bits = []
    try:
        bits.append(f'<span><b>{h["n_live"]}</b> exchanges live</span>')
    except Exception:
        pass
    try:
        cs = (_ENG.choke_state or {}).get(name) or {}
        x = cs.get("x")
        if x is not None and time.time() - cs.get("ts", 0) < 30:
            cls = "down" if x >= 3 else ("warn" if x >= 2 else "flat")
            bits.append(f'<span>order pace <b class="{cls}">{x:.1f}x</b> normal'
                        f'<i class="fa-gauge"><i class="{cls}" style="width:{min(100, x / 4 * 100):.0f}%"></i></i></span>')
    except Exception:
        pass
    ns = _NET_STATE.get(name) or {}
    if name == "BTC" and ns.get("count") is not None:
        bits.append(f'<span>network: <b>{ns["count"] // 1000:,}K</b> waiting &middot; {ns["fee"]} sat/vB'
                    + (f' ({ns["mult"]:.1f}x)' if ns.get("mult") else "") + '</span>')
    if name == "XRP" and ns.get("queue") is not None:
        bits.append(f'<span>ledger queue <b>{ns["queue"]}</b> / {ns["expected"]} &middot; fee {ns["fee_x"]:.0f}x</span>')
    return f'<div class="fa-status hint">{" &middot; ".join(bits)}</div>' if bits else ""


def build_alert_box(name):
    rows = _ENG.alerts_for(name, max_age=3600, limit=40)   # 2026-10-22 (user): scroll back through at least 30 buys / sells
    dec = 4 if name == "XRP" else 2
    items = []
    for a in rows:
        void = a["kind"] == "pulled"          # canceled / never filled: shown in white, not green / red
        side_cls = "void" if void else ("up" if a["side"] == "buy" else ("down" if a["side"] == "sell" else "flat"))
        arrow = "&#10005;" if void else "&#10227;" if a["kind"] == "moved" else ("<i class=va-u></i>" if a["side"] == "buy" else ("<i class=va-d></i>" if a["side"] == "sell" else "&#9679;"))
        fresh = " fa-fresh" if time.time() - a["ts"] < 20 else ""
        head, where = _alert_line(a, dec)
        usd_big = _usd_short(a["usd"]) if a.get("usd") else ""
        if usd_big and usd_big in head:
            head = head.replace(" " + usd_big, "").replace(usd_big, "").rstrip(" :")
        items.append(
            f'<div class="fa-item fa-sev{a["sev"]} fa-{side_cls}{fresh}" title="{_html_attr(a["detail"])}" data-alert-id="{name}::{a["id"]}" data-kind="{a["kind"]}" '
            f'data-side="{a["side"] or ""}" data-sev="{a["sev"]}" data-sound="{1 if a.get("sound") else 0}" data-ts="{a["ts"]:.0f}" '
            f'data-name="{name}" data-title="{_html_attr(a["title"])}" data-usd="{a.get("usd") or 0:.0f}">'
            f'<span class="fa-arrow {side_cls}">{arrow}</span> <b class="fa-head {side_cls}">{head}</b>'
            + (f' <span class="fa-usd">{usd_big}</span>' if usd_big else "")
            + (f' <span class="fa-where">{where}</span>' if where else "")
            + f'<span class="fa-age hint">{_ago(a["ts"])}</span><div class="fa-detail">{a["detail"]}</div></div>')
    if not items:
        items.append('<div class="hint fa-empty">Quiet &ndash; nothing big in the last hour.</div>')
    h = _flow.HUB.feed_health()
    lt = _ENG.liq_totals(name, 300)
    liq_txt = ""
    if lt["n"]:
        liq_txt = (f' &middot; forced sales, last 5 min: <span class="down">longs {_usd_short(lt["long"])}</span> / '
                   f'<span class="up">shorts {_usd_short(lt["short"])}</span>')
    return (f'<div class="top-w top-alerts"><div class="top-w-title">WHALE &amp; LIQUIDITY ALERTS <span class="hint">whales &middot; big orders &middot; '
            f'fake breakouts &middot; forced sales</span></div>'
            + _alert_status_line(name, h) +
            f'<div class="fa-list">{"".join(items)}</div>'
            f'<!--OWNER--><div class="hint fa-foot">{h["n_live"]} feed{"s" if h["n_live"] != 1 else ""} live{liq_txt}</div><!--/OWNER--></div>')


def _html_attr(s):
    return (str(s).replace("&", "&amp;").replace('"', "&quot;").replace("<", "&lt;").replace(">", "&gt;"))


def build_top_strip(name, d):
    try:
        rsi_w = build_rsi_flip_widget(name, d)
    except Exception as e:
        rsi_w = f'<div class="top-w hint">RSI meter error: {e!r}</div>'
    try:
        flip_w = build_flip_chance_widget(name, d)
    except Exception as e:
        flip_w = f'<div class="top-w hint">flip meter error: {e!r}</div>'
    try:
        alert_w = build_alert_box(name)
    except Exception as e:
        alert_w = f'<div class="top-w hint">alert box error: {e!r}</div>'
    return f'<div class="top-strip alerts-only">{alert_w}</div>'


def _never_break(fn):
    def w(*a, **k):
        try:
            return fn(*a, **k)
        except Exception as e:
            print(f"[render] {fn.__name__} failed: {e!r}")
            return ""
    w.__name__ = fn.__name__
    return w


_TIER_CLS = {"SUPER": "tier-super", "GOOD": "tier-good", "WEAK": "tier-weak"}


def _kalshi_at_lock(c):
    """Kalshi's price for the CALLED side at the moment the call locked (0-1), or None."""
    if not c or not c.get("call"):
        return None
    if c.get("kp") is not None:
        return c["kp"]
    ky = c.get("kalshi_yes")
    return (ky if c["call"] == "YES" else 1 - ky) if ky is not None else None


def _conf_lines(p_side, tier, kp, extra=""):
    """2026-10-22: BRAIN's own confidence + tier, and the Kalshi % the call locked at, on their own lines."""
    k = (f'<div class="sb-line sb-klock">Market at lock: <b>{kp:.0%}</b>{extra}</div>' if kp is not None
         else (f'<div class="sb-line sb-klock">{extra.lstrip(" &middot;")}</div>' if extra else ""))
    return f'<div class="sb-line sb-conf">BRAIN confidence: <b>{p_side:.0%}</b></div>{k}'


@_never_break
def build_stage_box(name, d, key):
    """The big EARLY (4:00) or SEALED (8:00) call box: direction, confidence tier (SUPER / GOOD / WEAK) or SKIPPED + why."""
    mark = {k: m for k, m, _l, _mk in STAGE_CALLS}[key]
    lab = {k: l for k, _m, l, _mk in STAGE_CALLS}[key]
    mk = {k: x for k, _m, _l, x in STAGE_CALLS}[key]
    dec = d.get("price_decimals", 2)
    c = (d.get("stage_calls") or {}).get(key) or {}
    cls = "stage-box" + (" stage-sealed" if key == "sealed" else " stage-early")
    title = f'{"<i class=ico data-i=lock></i> SEALED CALL" if key == "sealed" else "EARLY CALL"} &middot; {mk}'
    if c.get("call"):
        up = c["call"] == "YES"
        p_up = c.get("p_yes") or 0.5
        p_side = p_up if up else 1 - p_up
        tier = c.get("tier") or "GOOD"
        diff = (c["spot"] - c["line"]) if (c.get("spot") is not None and c.get("line")) else None
        live_kp = d.get("kalshi_price")
        holding = (live_kp if up else 1 - live_kp) if live_kp is not None else None
        cls += " stage-up" if up else " stage-down"
        hold_html = ""
        if holding is not None:
            # 2026-10-20 (user request): Kalshi's % is WHITE when Kalshi agrees with the call, BLACK when it disagrees -
            # the same in every call box, BTC and XRP, early and sealed. The whole 'Kalshi now' row changes colour, no background.
            agree = holding >= 0.5
            hold_html = (f'<div class="sb-line {"k-agree" if agree else "k-disagree"}"><span>Market {"agrees" if agree else "disagrees"} '
                         f'&middot; <b>{holding:.0%}</b></span></div>')
        z80 = (f'<div class="sb-z80"><i class=ico data-i=star></i> 80% SETUP &middot; won {c["zone80"]:.0%} in backtest'
               + (f' &middot; {c["zone80_roi"] * 100:+.0f}% per $ at market prices' if c.get("zone80_roi") is not None else "")
               + '</div>' if c.get("zone80") else "")
        rev = z80 + (f'<div class="sb-rev"><i class=ico data-i=reversal></i> REVERSAL{(" &middot; ~" + format(c["rev_payout"], ".1f") + "x") if c.get("rev_payout") else ""}</div>'
               if c.get("reversal") else "")
        body = (f'<div class="sb-dir {"up" if up else "down"}">{"<i class=va-u></i> UP" if up else "<i class=va-d></i> DOWN"}</div>{rev}'
                f'<div class="sb-tier {_TIER_CLS.get(tier, "")}">{tier}</div>'
                + _conf_lines(p_side, tier, _kalshi_at_lock(c),
                              (f' &middot; {c.get("crosses")} line cross{"" if c.get("crosses") == 1 else "es"} so far'
                               if c.get("crosses") is not None else ""))
                + (f'<div class="sb-line">{"+" if diff >= 0 else "-"}{fmt_price(abs(diff), dec)} vs. the line, locked at {c.get("elapsed", 0) // 60}:{c.get("elapsed", 0) % 60:02d}</div>' if diff is not None else "")
                + hold_html
                + ('' if c.get("radar_agree") is None else
                   f'<div class="sb-line"><i class=ico data-i=radar></i> Top traders {"agree" if c["radar_agree"] else "lean the other way"}</div>')
                + _sig_html(c.get("signals"))
                + (f'<!--OWNER--><div class="sb-note">{c["why"]}</div><!--/OWNER-->' if c.get("why") else ""))
        tip = "locked call - graded when the round settles"
    elif c.get("skipped") and key == "sealed" and ((d.get("stage_calls") or {}).get("late") or {}).get("call"):
        lt = d["stage_calls"]["late"]
        up = lt["call"] == "YES"
        cls += " stage-up" if up else " stage-down"
        el_ = lt.get("elapsed", 0)
        live_kp = d.get("kalshi_price")
        holding = (live_kp if up else 1 - live_kp) if live_kp is not None else None
        hold_html = ""
        if holding is not None:
            agree = holding >= 0.5
            hold_html = (f'<div class="sb-line {"k-agree" if agree else "k-disagree"}"><span>Market {"agrees" if agree else "disagrees"} '
                         f'&middot; <b>{holding:.0%}</b></span></div>')
        p_side = (lt.get("p_yes") or 0.5) if up else 1 - (lt.get("p_yes") or 0.5)
        body = (f'<div class="sb-late"><i class=ico data-i=clock></i> LATE CALL &middot; PRICE HAS DECIDED</div>'
                f'<div class="sb-dir {"up" if up else "down"}">{"<i class=va-u></i> UP" if up else "<i class=va-d></i> DOWN"}</div>'
                f'<div class="sb-tier {_TIER_CLS.get(lt.get("tier") or "GOOD", "")}">{lt.get("tier") or "GOOD"}</div>'
                + _conf_lines(p_side, lt.get("tier") or "GOOD", _kalshi_at_lock(lt), f' &middot; called at {el_ // 60}:{el_ % 60:02d}')
                + hold_html +
                f'<div class="sb-line hint">Sat out at 8:00 - {_html_attr(c.get("why") or "")}</div>')
        tip = "the sealed call sat this round out, then price clearly decided"
    elif c.get("skipped"):
        cls += " stage-skip"
        lean = c.get("lean")
        if c.get("sitout") and lean:
            body = (f'<div class="sb-dir flat">SIT THIS ONE OUT</div><div class="sb-tier tier-skip">NO CALL</div>'
                    f'<div class="sb-line">Leaning <b class="{"up" if lean == "YES" else "down"}">{"UP" if lean == "YES" else "DOWN"}</b> '
                    f'{max(c.get("p_yes") or 0.5, 1 - (c.get("p_yes") or 0.5)):.0%}</div>'
                    f'<div class="sb-line hint">{_html_attr(c.get("why") or "")}</div>'
                    + ('<div class="sb-line hint">Watching for price to decide - a late call can still come.</div>' if key == "sealed" else ""))
        else:
            body = (f'<div class="sb-dir flat">NO CALL</div><div class="sb-tier tier-skip">SKIPPED</div>'
                    f'<div class="sb-line">{c.get("why", "")}</div>'
                    f'<div class="sb-line hint">It was leaning {"UP" if (c.get("p_yes") or 0.5) >= 0.5 else "DOWN"} '
                    f'{max(c.get("p_yes") or 0.5, 1 - (c.get("p_yes") or 0.5)):.0%}</div>')
        tip = "sits out a choppy or dead round instead of guessing"
    elif c.get("missed"):
        body = (f'<div class="sb-dir flat">MISSED</div><div class="sb-line">The dashboard wasn&#39;t running at {mk} this round.</div>')
        tip = "only locks live at its mark - never back-filled"
    else:
        el = d.get("elapsed_seconds") or 0
        wait = max(0, int(mark - el))
        p = d.get("stage_p_yes")
        ls = d.get("line_stats") or {}
        prev = ""
        if p is not None:
            sg = d.get("stage_sig") or {}
            pc, pt, pw = stage_decide(p, (d.get("stage_parts") or {}).get("flow"), ls.get("crosses"), signals=sg)
            _cs, _ag, _op = signal_consensus(sg)
            if max(p, 1 - p) < STAGE_CALL_MIN and not (_cs and _ag >= 3 and _op == 0):
                pc = None
                pw = "a coin flip right now - it will wait up to 60s"
            try:
                _rv = reversal_check(name, d.get("spot_price"), d.get("target_price"), d.get("seconds_left"), el, ls,
                                     d.get("rsi_multi"), sg, d.get("kalshi_price"), d.get("ticker"), stage=key)
            except Exception:
                _rv = None
            # 2026-10-22 (user): no "reversal" talk until the early call is in - only the sealed preview can show one
            _early_in = bool(((d.get("stage_calls") or {}).get("early") or {}).get("call"))
            if _rv and _rv["call"] != pc and key == "sealed" and _early_in:
                pc, pt = _rv["call"], _rv["tier"] + " <i class=ico data-i=reversal></i> REVERSAL" + (f' ~{_rv["payout"]:.1f}x' if _rv.get("payout") else "")
            if pc:
                prev = (f'<div class="sb-line">Right now: <span class="{"up" if pc == "YES" else "down"}"><b>{"UP" if pc == "YES" else "DOWN"} '
                        f'{pt}</b></span></div>')
            else:
                prev = f'<div class="sb-line">Right now: <span class="flat"><b>it would skip</b></span> ({pw})</div>'
        # 2026-10-22 (user): live countdown right in the tile - no separate "time until call" box
        if wait > 0:
            _to = int(time.time()) + wait
            cd = (f'<div class="stage-cd"><span class="hint">locks in</span> '
                  f'<span class="stage-cd-t" data-to="{_to}">{wait // 60}:{wait % 60:02d}</span></div>')
        else:
            cd = '<div class="stage-cd"><span class="stage-cd-t now">LOCKING NOW</span></div>'
        body = (f'<div class="stage-pend">PENDING</div>{cd}{prev}{_sig_html(d.get("stage_sig"))}')
        tip = "locks automatically at the mark and is graded at settlement"
    rec = stage_record(_history.get(name, []), key)
    rec_html = (f'<div class="sb-rec">{rec["wins"]}/{rec["n"]} right ({rec["wins"] / rec["n"]:.0%})</div>' if rec["n"]
                else "")
    alert = ""
    if (c.get("call") or c.get("skipped")) and (d.get("stage_just") == key or time.time() - (c.get("ts") or 0) < 25):
        alert = (f'<span class="stage-alert" data-name="{name}" data-stage="{key}" data-call="{c.get("call") or ""}" '
                 f'data-tier="{c.get("tier") or ""}" data-why="{_html_attr(c.get("why") or "") if not c.get("call") else ""}" data-rev="{1 if c.get("reversal") else 0}" data-lean="{c.get("lean") or ""}" data-sitout="{1 if c.get("sitout") else 0}" '
                 f'data-sure="{round(max(c.get("p_yes") or 0.5, 1 - (c.get("p_yes") or 0.5)) * 100)}" '
                 f'data-kp="{round(_kalshi_at_lock(c) * 100) if _kalshi_at_lock(c) is not None else ""}" '
                 f'data-key="{name}::{d.get("ticker", "")}::{key}" style="display:none;"></span>')
    lt_ = (d.get("stage_calls") or {}).get("late") or {}
    if key == "sealed" and lt_.get("call") and (d.get("stage_just") == "late" or time.time() - (lt_.get("ts") or 0) < 25):
        alert += (f'<span class="stage-alert" data-name="{name}" data-stage="late" data-call="{lt_["call"]}" data-tier="{lt_.get("tier") or ""}" '
                  f'data-why="" data-rev="0" data-lean="" data-sitout="0" '
                  f'data-sure="{round(max(lt_.get("p_yes") or 0.5, 1 - (lt_.get("p_yes") or 0.5)) * 100)}" '
                  f'data-kp="{round(_kalshi_at_lock(lt_) * 100) if _kalshi_at_lock(lt_) is not None else ""}" '
                  f'data-key="{name}::{d.get("ticker", "")}::late" style="display:none;"></span>')
    return (f'<div class="{cls}" title="{_html_attr(tip)}"><div class="sb-title">{title}</div>{body}{rec_html}{alert}</div>')


@_never_break
def _sig_html(sig):
    if not sig:
        return ""
    bits = []
    for k, lab in SIGNAL_NAMES:
        v = sig.get(k, 0)
        bits.append(f'<span class="{"up" if v > 0 else ("down" if v < 0 else "flat")}">{lab} {"<i class=va-u></i>" if v > 0 else ("<i class=va-d></i>" if v < 0 else "&#8211;")}</span>')
    cs, agree, oppose = signal_consensus(sig)
    tail = (f' &middot; <b>{agree} of {len(sig)} {"UP" if cs > 0 else "DOWN"}</b>' if cs else " &middot; <b>mixed</b>")
    return f'<!--OWNER--><div class="sb-sig">{" ".join(bits)}{tail}</div><!--/OWNER-->'


def stage_summary_row(name, d):
    """Track record per call and per confidence tier, with $100-a-call P&L."""
    hist = _history.get(name, [])
    bits = []
    for key, _m, lab, mk in STAGE_CALLS:
        r = stage_record(hist, key)
        if not r["n"]:
            bits.append(f'{lab} ({mk}): <span class="flat">no graded rounds yet</span>')
            continue
        tiers = []
        for t in ("SUPER", "GOOD", "WEAK"):
            rows = [h for h in hist if h.get(f"{key}_tier") == t and h.get(f"{key}_correct") is not None]
            if rows:
                w_ = sum(1 for h in rows if h[f"{key}_correct"])
                tiers.append(f'<span class="{_TIER_CLS[t]}">{t.lower()}</span> {w_}/{len(rows)}')
        bits.append(f'{lab} ({mk}): <b>{r["wins"]}/{r["n"]}</b> ({r["wins"] / r["n"]:.0%}) '
                    + (f'<span class="hint">[{" &middot; ".join(tiers)}]</span> ' if tiers else "")
                    + f'<span class="{"up" if r["pnl"] >= 0 else "down"}">{r["pnl"]:+,.0f} on $100/call</span>')
    ls = d.get("line_stats") or {}
    cr = ""
    if ls:
        n = ls.get("crosses", 0)
        cr = (f'<!--OWNER--><div class="row cross-row"><span class="label">Line crosses this round</span><span class="value">'
              f'<b class="{"down" if n >= CROSS_SKIP else ("warn" if n == 2 else "up")}" style="font-size:18px;">{n}</b> '
              f'<span class="hint">{"choppy" if n >= 3 else "clean"}</span></span></div><!--/OWNER-->')
    return cr      # the per-call track record now lives in the SCOREBOARD at the top


def _round_svg(rec, w=300, h=96, live=False):
    path = rec.get("path") or []
    if len(path) < 2:
        return f'<svg viewBox="0 0 {w} {h}" width="100%" height="{h}"><text x="{w / 2}" y="{h / 2}" text-anchor="middle" fill="#bcaaa1" font-size="11">collecting...</text></svg>'
    m = max(0.01, max(abs(y) for _x, y in path)) * 1.15
    X = lambda e: max(0.0, min(900.0, e)) / 900 * w
    Y = lambda v: h / 2 - v / m * (h / 2 - 4)
    pts = " ".join(f"{X(e):.1f},{Y(v):.1f}" for e, v in path)
    area = f"{X(path[0][0]):.1f},{h / 2:.1f} " + pts + f" {X(path[-1][0]):.1f},{h / 2:.1f}"
    cid = f'c{abs(hash((rec.get("ticker"), live))) % 10 ** 8}'
    out = [f'<defs><clipPath id="{cid}a"><rect x="0" y="0" width="{w}" height="{h / 2}"/></clipPath>'
           f'<clipPath id="{cid}b"><rect x="0" y="{h / 2}" width="{w}" height="{h / 2}"/></clipPath></defs>',
           f'<polygon points="{area}" fill="#3dd69c" fill-opacity="0.22" clip-path="url(#{cid}a)"/>',
           f'<polygon points="{area}" fill="#f05454" fill-opacity="0.22" clip-path="url(#{cid}b)"/>']
    for e, lbl in ((240, "4:00"), (480, "8:00")):
        out.append(f'<line x1="{X(e):.1f}" y1="0" x2="{X(e):.1f}" y2="{h}" stroke="#dcbb91" stroke-dasharray="2 3" stroke-width="1" opacity="0.7"/>'
                   f'<text x="{X(e) + 2:.1f}" y="10" fill="#f6d9e2" font-size="9">{lbl}</text>')
    out.append(f'<line x1="0" y1="{h / 2}" x2="{w}" y2="{h / 2}" stroke="#fbf4ec" stroke-width="1" opacity="0.55"/>')
    out.append(f'<polyline points="{pts}" fill="none" stroke="#fbf4ec" stroke-width="1.6"/>')
    for e, sd in rec.get("events") or []:
        out.append(f'<circle cx="{X(e):.1f}" cy="{h / 2}" r="3.2" fill="{"#3dd69c" if sd > 0 else "#f05454"}" stroke="#211b1e" stroke-width="1"/>')
    return f'<svg viewBox="0 0 {w} {h}" width="100%" height="{h}" preserveAspectRatio="none">{"".join(out)}</svg>'


def _round_label(ticker):
    t = _window_close_utc(ticker)
    if not t:
        return ticker or "?"
    o = (t - dt.timedelta(minutes=15)).astimezone(ZoneInfo("America/New_York"))
    c = t.astimezone(ZoneInfo("America/New_York"))
    return f'{o.strftime("%I:%M").lstrip("0")}&ndash;{c.strftime("%I:%M %p").lstrip("0")}'


def _kalshi_spark(pts, w=300, h=54):
    if not pts or len(pts) < 2:
        return f'<svg viewBox="0 0 {w} {h}" width="100%" height="{h}"></svg>'
    X = lambda e: max(0, min(900, e)) / 900 * w
    Y = lambda v: h - v * h
    line = " ".join(f"{X(e):.1f},{Y(v):.1f}" for e, v in pts)
    last = pts[-1][1]
    col = "#3dd69c" if last >= 0.5 else "#f05454"
    marks = "".join(f'<line x1="{X(e):.1f}" y1="0" x2="{X(e):.1f}" y2="{h}" stroke="#dcbb91" stroke-dasharray="2 3" opacity="0.6"/>'
                    for e in (240, 480))
    return (f'<svg viewBox="0 0 {w} {h}" width="100%" height="{h}" preserveAspectRatio="none">{marks}'
            f'<line x1="0" y1="{h / 2}" x2="{w}" y2="{h / 2}" stroke="#bcaaa1" stroke-dasharray="3 3" opacity="0.6"/>'
            f'<polyline points="{line}" fill="none" stroke="{col}" stroke-width="2.2"/>'
            f'<circle cx="{X(pts[-1][0]):.1f}" cy="{Y(last):.1f}" r="3.5" fill="{col}"/></svg>')


# 2026-10-22 (user): the "Market live" % at the top must refresh every few seconds. The main loop's price for
# XRP comes from the ~30s-cached list endpoint (on purpose, for its CALLS), and both coins only refresh as fast as
# the loop runs. This poller reads the live order book for every active round every ~1.5s - display only.
_LIVE_ODDS = {}            # ticker -> (mid yes price, epoch seconds)


# 2026-10-22 (user): "the blockchain getting clogged with pending - a break-through gauge, maybe just an alert that pops up with
# the whale & liquidity alerts". Bitcoin: mempool.space (unconfirmed transactions + fees). XRP: the XRPL fee queue.
_NET_STATE = {"BTC": {}, "XRP": {}}


def _network_loop():
    import requests as _rq
    fee_hist = collections.deque(maxlen=60)
    while True:
        try:
            m = _rq.get("https://mempool.space/api/mempool", timeout=8).json()
            f = _rq.get("https://mempool.space/api/v1/fees/recommended", timeout=8).json()
            cnt, vmb, fast = m.get("count") or 0, (m.get("vsize") or 0) / 1e6, f.get("fastestFee") or 0
            fee_hist.append(fast)
            base = sorted(fee_hist)[len(fee_hist) // 2] if len(fee_hist) >= 5 else None
            mult = (fast / base) if base else None
            _NET_STATE["BTC"] = {"count": cnt, "vmb": round(vmb, 1), "fee": fast, "mult": round(mult, 2) if mult else None, "ts": time.time()}
            clogged = vmb >= 100 or (mult is not None and mult >= 2.5 and fast >= 10)
            if clogged:
                _ENG.add_alert("BTC", "mempool", "flat", f"BITCOIN NETWORK CLOGGED: {cnt:,} TRANSACTIONS WAITING",
                               f"{vmb:.0f} MB of unconfirmed transactions; the fast fee is {fast} sat/vB"
                               + (f" ({mult:.1f}x the last hour's normal)" if mult else "")
                               + ". A jam like this often means coins are being rushed onto exchanges - big moves can follow.",
                               sev=2, sound=False, cooldown_key=("mempool", "BTC"), cooldown=1200)
        except Exception as _e:
            _NET_STATE["BTC"] = {"error": repr(_e)[:80], "ts": time.time()}
        try:
            r = _rq.post("https://xrplcluster.com/", json={"method": "fee", "params": [{}]}, timeout=8).json().get("result") or {}
            q, exp = int(r.get("current_queue_size") or 0), int(r.get("expected_ledger_size") or 0)
            of_ = int((r.get("drops") or {}).get("open_ledger_fee") or 0)
            bf = int((r.get("drops") or {}).get("base_fee") or 10) or 10
            _NET_STATE["XRP"] = {"queue": q, "expected": exp, "fee_x": round(of_ / bf, 1), "ts": time.time()}
            if (exp and q >= exp) or of_ >= 20 * bf:
                _ENG.add_alert("XRP", "mempool", "flat", f"XRP LEDGER CLOGGED: {q:,} TRANSACTIONS QUEUED",
                               f"{q:,} transactions are waiting for the next ledger (it holds about {exp:,}); the open-ledger fee is "
                               f"{of_ / bf:.0f}x normal. Heavy on-chain traffic like this often comes with big moves.",
                               sev=2, sound=False, cooldown_key=("mempool", "XRP"), cooldown=1200)
        except Exception as _e:
            _NET_STATE["XRP"] = {"error": repr(_e)[:80], "ts": time.time()}
        time.sleep(60)


def _live_odds_loop():
    while True:
        try:
            for _n, _d in list(_state.items()):
                _t = (_d or {}).get("ticker")
                if not _t:
                    continue
                _q = get_live_yes_bid_ask(_t)
                if _q and (_q[0] or _q[1]):
                    _LIVE_ODDS[_t] = ((_q[0] + _q[1]) / 2, time.time())
        except Exception as _e:
            print(f"[live odds] {_e!r}")
        time.sleep(1.5)


def _live_kp(d):
    """Freshest market YES price for display: the fast poller if it is < 8s old, else the loop's value."""
    _lo = _LIVE_ODDS.get(d.get("ticker") or "")
    if _lo and time.time() - _lo[1] < 8:
        return _lo[0]
    return d.get("kalshi_price")


def _kalshi_line(d):
    kp = _live_kp(d)
    if kp is None:
        return ""
    up = round(kp * 100)
    edge = abs(kp - 0.5)
    side = "UP" if kp >= 0.5 else "DOWN"
    lean = "50/50" if edge < 0.02 else (f"leaning {side}" if edge < 0.25 else f"strongly {side}")
    return (f'<div class="k-line"><div class="k-nums"><span class="up">UP {up}%</span><span class="k-lean">Market live &middot; {lean}</span>'
            f'<span class="down">{100 - up}% DOWN</span></div><div class="k-bar"><i style="width:{up}%"></i><b></b></div></div>')


@_never_break
def build_kalshi_tile(name, d):
    kp = d.get("kalshi_price")
    if kp is None:
        return '<div class="rs-tile rs-odds"><div class="rs-title">MARKET ODDS &middot; LIVE</div><div class="rs-wait">waiting for the market&#39;s price...</div></div>'
    up = round(kp * 100)
    dn = 100 - up
    edge = abs(kp - 0.5)
    side = "UP" if kp >= 0.5 else "DOWN"
    if edge < 0.02:
        lean, lcls = "50/50 - no lean", "flat"
    elif edge < 0.10:
        lean, lcls = f"leaning {side} (slight)", "up" if side == "UP" else "down"
    elif edge < 0.25:
        lean, lcls = f"leaning {side}", "up" if side == "UP" else "down"
    else:
        lean, lcls = f"strongly {side}", "up" if side == "UP" else "down"
    pts = d.get("kalshi_path") or []
    chg = ""
    if len(pts) >= 2:
        now_e = pts[-1][0]
        ref = next((v for e, v in reversed(pts) if now_e - e >= 30), pts[0][1])
        c = round((pts[-1][1] - ref) * 100)
        if c:
            chg = f'<span class="{"up" if c > 0 else "down"}">{"<i class=va-u></i>" if c > 0 else "<i class=va-d></i>"} UP {c:+d}&cent; in the last 30s</span>'
        else:
            chg = '<span class="flat">steady over the last 30s</span>'
    mins, secs = divmod(max(0, int(d.get("seconds_left") or 0)), 60)
    return (f'<div class="rs-tile rs-odds"><div class="rs-title">MARKET ODDS &middot; LIVE <span class="rs-clock">{mins}:{secs:02d} left</span></div>'
            f'<div class="rs-odds-nums"><span class="up">UP <b>{up}%</b></span><span class="down"><b>{dn}%</b> DOWN</span></div>'
            f'<div class="rs-odds-bar"><i style="width:{up}%"></i><b></b></div>'
            f'<div class="rs-lean {lcls}">{lean}</div>{_kalshi_spark(pts)}<div class="rs-sub">{chg}'
            f'<span class="hint">This round &middot; dashed lines mark 4:00 and 8:00</span></div></div>')


@_never_break
def build_rsi_box(name, d):
    """One small RSI(14) box: the number, colour-coded - OVERSOLD (30 or less), BEARISH (30-45), NORMAL (45-55), BULLISH (55-70),
    OVERBOUGHT (70 or more). Since 2026-10-20 the big number is TradingView's Wilder RSI(14) on Coinbase 1-minute candles (live
    candle included), cross-checked against a Webull-style simple-average RSI and BRAIN's all-exchange composite."""
    rm = d.get("rsi_multi") or {}
    r = rm.get("rsi1")
    # 2026-10-22: show whichever method the daily backtest found reads the round better (default TradingView)
    _ck0 = rm.get("check") or {}
    try:
        _rcb = ((_bt.load_saved() or {}).get("rsi_check") or {}).get("sealed") or {}
    except Exception:
        _rcb = {}
    _pick = _rcb.get("pick") or "tradingview"
    if _pick == "webull" and _ck0.get("wb1") is not None:
        r = _ck0["wb1"]
    if r is None:
        return '<div class="rs-tile rsi-box"><div class="rs-title">RSI (14)</div><div class="rsi-num flat">--</div><div class="rsi-zone flat">warming up</div></div>'
    if r >= 70:
        z, c = "OVERBOUGHT", "rz-ob"
    elif r >= 55:
        z, c = "BULLISH", "rz-bull"
    elif r > 45:
        z, c = "NORMAL", "rz-norm"
    elif r > 30:
        z, c = "BEARISH", "rz-bear"
    else:
        z, c = "OVERSOLD", "rz-os"
    r5 = rm.get("rsi5")
    ck = rm.get("check") or {}
    chk = ""
    if ck:
        def _n(v):
            return f"{v:.0f}" if v is not None else "--"
        ok = ck.get("agree")
        gap = ck.get("gap_wb")
        verdict = ('<span class="rc-ok"><i class=ico data-i=check></i> matches</span>' if ok
                   else f'<span class="rc-off"><i class=ico data-i=warn></i> {gap:.0f} pts apart</span>' if gap is not None else "")
        tip = (f'Big number = TradingView RSI(14), {ck.get("source")} 1-min, live candle included ({ck.get("bars1")} candles). '
               f'5-min: TradingView {_n(ck.get("tv5"))} / Webull-style {_n(ck.get("wb5"))}. ' + (ck.get("pick_why") or ""))
        _acc = lambda m: (_rcb.get(m) or {}).get("acc")
        _tv_acc, _wb_acc = _acc("tradingview"), _acc("webull")
        _star_tv = "<i class=ico data-i=star></i> " if _pick == "tradingview" else ""
        _star_wb = "<i class=ico data-i=star></i> " if _pick == "webull" else ""
        _avg = ((ck.get("tv1") + ck.get("wb1")) / 2) if (ck.get("tv1") is not None and ck.get("wb1") is not None) else None
        _bt_line = (f'backtest: TradingView {_tv_acc * 100:.0f}% vs Webull {_wb_acc * 100:.0f}% right'
                    if (_tv_acc is not None and _wb_acc is not None) else "backtest pending")
        chk = (f'<div class="rsi-check" title="{_html_attr(tip)}">'
               f'<div class="rc-row{" rc-pick" if _pick == "tradingview" else ""}"><span>{_star_tv}TradingView</span><b>{_n(ck.get("tv1"))}</b></div>'
               f'<div class="rc-row{" rc-pick" if _pick == "webull" else ""}"><span>{_star_wb}Webull</span><b>{_n(ck.get("wb1"))}</b></div>'
               f'<div class="rc-row"><span>Avg of both</span><b>{_n(_avg)}</b></div>'
               f'<div class="rc-verdict">{verdict}</div></div>')
    src = ("TradingView method" if _pick == "tradingview" else "Webull method") if ck else "all exchanges"
    return (f'<div class="rs-tile rsi-box {c}"><div class="rs-title">RSI (14)</div><div class="rsi-num">{r:.0f}</div>'
            f'<div class="rsi-zone">{z}</div><div class="rsi-sub">{f"5-min {r5:.0f}" if r5 is not None else "1-min"}</div>{chk}'
            f'<span class="rsi-marker" data-rsi-name="{name}" data-rsi="{r:.1f}" style="display:none;"></span></div>')


def _result_chip(ok, actual):
    """2026-10-22 (user): the circle's COLOR is how the round ended (green = settled UP, red = settled DOWN), the LETTER is
    whether BRAIN's call was right. Called DOWN + ended DOWN = red W; called UP + ended UP = green W; called DOWN but ended
    UP = green L; called UP but ended DOWN = red L."""
    col = "cu" if actual == "YES" else ("cd" if actual == "NO" else ("w" if ok else "l"))
    end = {"YES": "ended UP", "NO": "ended DOWN"}.get(actual, "")
    return f'<i class="{col}{" ok" if ok else ""}" title="{"win" if ok else "loss"}{(" - " + end) if end else ""}">{"W" if ok else "L"}</i>'


@_never_break
def build_streak_box(name, d):
    """Win / loss streak tile (2026-10-20): the sealed call's current run big, the early call's run under it, and the last 8
    sealed results. Gold = win, lavender = loss - kept off green/red so it is never read as UP/DOWN."""
    hist = _history.get(name, [])
    runs = {}
    acts = {}
    for key, field in (("sealed", "sealed_correct"), ("early", "early_correct")):
        _ok = [h for h in hist if h.get(field) is not None and not h.get(f"{key}_reversal")]
        res = [bool(h[field]) for h in _ok]
        acts[key] = [h.get("actual_side") for h in _ok]
        runs[key] = (res, _streak_stats(res) if res else (None, 0, 0, 0))
    sres, (st, sn, sbw, sbl) = runs["sealed"]
    eres, (et_, en, ebw, _ebl) = runs["early"]
    if not sres and not eres:
        return ('<div class="rs-tile sk-box"><div class="rs-title">STREAK</div><div class="sk-num flat">--</div>'
                '<div class="sk-zone flat">no results yet</div></div>')
    if sres:
        cls, big, zone = ("sk-win", f"{sn}W", "SEALED &middot; WINS") if st else ("sk-loss", f"{sn}L", "SEALED &middot; LOSSES")
        if sn == 1:
            zone = zone.replace("WINS", "WIN").replace("LOSSES", "LOSS")
    else:
        cls, big, zone = ("sk-win", f"{en}W", "EARLY &middot; WIN") if et_ else ("sk-loss", f"{en}L", "EARLY &middot; LOSS")
    early = (f'early <b class="{"skw" if et_ else "skl"}">{en}{"W" if et_ else "L"}</b>' if eres and sres else "")
    best = (f'best <b class="skw">{sbw}W</b> &middot; worst <b class="skl">{sbl}L</b>' if sres else "") + (
        f' &middot; early best <b class="skw">{ebw}W</b>' if eres and sres else "")
    _ca = acts["sealed"] if sres else acts["early"]
    chips = "".join(_result_chip(r_, a_) for r_, a_ in list(zip(sres or eres, _ca))[-8:])
    sub = " &middot; ".join(x for x in (early, best) if x)
    return (f'<div class="rs-tile sk-box {cls}"><div class="rs-title">STREAK</div><div class="sk-num">{big}</div>'
            f'<div class="sk-zone">{zone}</div><div class="sk-sub">{sub}</div><div class="sk-chips">{chips}</div></div>')


TWAP_WINDOW_S = 60          # CF Benchmarks / Kalshi settle on the average of the final 60 one-second index values
TWAP_LOCK_PCT = 0.25        # the average still needed sits this % (or more) from live price = effectively LOCKED


def twap_lock(name, d):
    """Final-minute settlement projection (2026-10-20). Kalshi settles the 15-min round on the 60-second average of the
    CF Benchmarks index over the last minute, so a spike with 10s left barely moves it. Samples the spot-only blended
    price once a second from the tick tape over the final minute and returns the running average, how many seconds are
    left, and the average the REMAINING seconds need to finish exactly on the line."""
    strike = d.get("target_price")
    close = _window_close_utc(d.get("ticker"))
    if not strike or close is None:
        return None
    close_ts = close.timestamp()
    now = time.time()
    if now < close_ts - TWAP_WINDOW_S or now > close_ts + 30:
        return None
    sym = {a["name"]: a["symbol"] for a in DASHBOARD_ASSETS}.get(name)
    ticks = get_tick_history(sym) if sym else []
    if not ticks:
        return None
    samples, i, last = [], 0, None
    start = int(close_ts) - TWAP_WINDOW_S + 1
    for sec in range(start, int(min(now, close_ts)) + 1):
        while i < len(ticks) and ticks[i][0] <= sec:
            last = ticks[i][1]
            i += 1
        if last is not None:
            samples.append(last)
    if not samples:
        return None
    n = len(samples)
    total = sum(samples)
    avg = total / n
    remaining = max(0, TWAP_WINDOW_S - n)
    need = (strike * TWAP_WINDOW_S - total) / remaining if remaining else None
    spot = d.get("spot_price") or samples[-1]
    reach = abs(need - spot) / spot * 100 if (need is not None and spot) else None
    return {"avg": avg, "n": n, "remaining": remaining, "need": need, "strike": strike, "spot": spot,
            "side": "UP" if avg >= strike else "DOWN", "reach": reach,
            "locked": reach is not None and reach >= TWAP_LOCK_PCT, "final": remaining == 0}


@_never_break
def build_twap_lock(name, d):
    t = twap_lock(name, d)
    if not t:
        return ""
    dec = 4 if name == "XRP" else 2
    up = t["side"] == "UP"
    cls = "up" if up else "down"
    head = (f'<div class="lbl" style="margin-top:4px;">PROJECTED SETTLEMENT (60s avg) &middot; {t["n"]}/{TWAP_WINDOW_S}s</div>'
            f'<div class="twap-avg {cls}">{fmt_price(t["avg"], dec)} {"<i class=va-u></i> UP" if up else "<i class=va-d></i> DOWN"}</div>')
    if t["final"]:
        sub = '<div class="twap-need hint">final average - settling now</div>'
    else:
        lock = ' <b class="warn">LOCKED</b>' if t["locked"] else ""
        sub = (f'<div class="twap-need" title="the average price the remaining seconds need for the 60s average to land exactly on the line">'
               f'next {t["remaining"]}s must average {"under" if up else "over"} <b>{fmt_price(t["need"], dec)}</b> to flip '
               f'<span class="hint">({t["reach"]:.2f}% from live)</span>{lock}</div>')
    return f'<div class="twap-lock">{head}{sub}</div>'


# ---------------------------------------------------------------- FLIP RADAR (rebuilt 2026-10-20)
# No longer a mirror of Kalshi's price (Kalshi odds lag raw order flow, and traders stop bidding the other side late in
# the round). A 0-99% composite flip-risk score for the call on screen, from the live feeds the dashboard already has:
#   1. opposing momentum  (0-40)  - opposing taker share 10s/30s/1m + net dollars against the call while price moves at the line
#   2. cushion + crosses  (0-40)  - % distance from the line, +5 per line cross (recent crosses weigh more); wrong side = 75 floor
#   3. order book walls (-15..+20) - every exchange's resting bids vs asks: walls defending the call vs walls pressing on it
#   x  pace (0.75-1.35x) and time (final 90s with a solid cushion, and the 60-second settlement average) dampeners
FLIP_OPP_DELTA_USD = {"BTC": 1_200_000, "XRP": 150_000}   # net dollars against the call (30s + 1m) that counts as "strong"
FLIP_TIERS = ((20, "LOW", "up"), (45, "WATCH", "warn"), (70, "HIGH", "fr-high"), (99, "CRITICAL", "down"))


def _lerp(x, x0, x1, y0, y1):
    if x <= x0:
        return y0
    if x >= x1:
        return y1
    return y0 + (y1 - y0) * (x - x0) / (x1 - x0)


# ---- 2026-10-23 (user): "factor in the rejections and holds on the support channels from the chart, the line crosses, MACD
# and RSI". The same support / resistance zones the live chart shades (lwLevels in the page: swing highs / lows clustered into
# tight $ bands, "Rejected N times" / "Held N times"), plus RSI(14) and MACD(12,26,9) on the same 1-minute candles. Re-read at
# most every 5 seconds per coin, so the radar costs nothing extra on the 1-second refresh.
_chart_read_cache = {}


def _wilder_rsi(cl, n=14):
    if len(cl) < n + 2:
        return None, None
    g = l = 0.0
    for i in range(1, n + 1):
        d_ = cl[i] - cl[i - 1]
        g += max(d_, 0); l += max(-d_, 0)
    g /= n; l /= n
    out = []
    for i in range(n + 1, len(cl)):
        d_ = cl[i] - cl[i - 1]
        g = (g * (n - 1) + max(d_, 0)) / n
        l = (l * (n - 1) + max(-d_, 0)) / n
        out.append(100.0 if l == 0 else 100 - 100 / (1 + g / l))
    if len(out) < 4:
        return None, None
    return out[-1], out[-4]


def _ema_series(vals, n):
    k = 2 / (n + 1)
    e, out = vals[0], []
    for v in vals:
        e = v * k + e * (1 - k)
        out.append(e)
    return out


def _sr_zones(B):
    """Python twin of the chart's lwLevels: nearest resistance + support bands with their touch counts."""
    n = len(B)
    if n < 30:
        return [], 0.0
    px = B[-1][4]
    atr = sum(b[2] - b[3] for b in B[-20:]) / 20
    piv = []
    for i in range(2, n - 2):
        hi = all(B[j][2] < B[i][2] for j in range(i - 2, i + 3) if j != i)
        lo = all(B[j][3] > B[i][3] for j in range(i - 2, i + 3) if j != i)
        if hi:
            piv.append(B[i][2])
        if lo:
            piv.append(B[i][3])
    tol, minw = max(atr * 0.5, px * 0.00025), max(atr * 0.35, px * 0.0001)
    maxw = max(atr * 1.1, minw * 2)
    zones = []
    for p_ in sorted(piv):
        z = next((z for z in zones if p_ - z["hi"] <= tol and p_ - z["lo"] <= maxw), None)
        if z:
            z["hi"] = max(z["hi"], p_); z["n"] += 1
        else:
            zones.append({"lo": p_, "hi": p_, "n": 1})
    for z in zones:
        if z["hi"] - z["lo"] < minw:
            m = (z["hi"] + z["lo"]) / 2
            z["lo"], z["hi"] = m - minw / 2, m + minw / 2
        z["mid"] = (z["lo"] + z["hi"]) / 2
    res = sorted([z for z in zones if z["mid"] > px], key=lambda z: z["mid"])
    sup = sorted([z for z in zones if z["mid"] <= px], key=lambda z: -z["mid"])
    pick = lambda L: ([z for z in L if z["n"] >= 2] or L)[:2]
    out = [dict(z, r=True) for z in pick(res)] + [dict(z, r=False) for z in pick(sup)]
    return out, atr


def chart_read(name):
    """{"rsi", "rsi_prev", "hist", "hist_prev", "macd", "zones", "atr", "last"} from 1-minute candles, or None."""
    now = time.time()
    c = _chart_read_cache.get(name)
    if c and now - c[0] < 5:
        return c[1]
    out = None
    try:
        sym = {a["name"]: a["symbol"] for a in DASHBOARD_ASSETS}.get(name)
        cs = _mtf.books[sym].series(60, 180) if (_mtf is not None and sym in _mtf.books) else None
        if cs and len(cs) >= 40:
            cl = [x[4] for x in cs]
            r, rp = _wilder_rsi(cl)
            m = [a - b for a, b in zip(_ema_series(cl, 12), _ema_series(cl, 26))]
            sg = _ema_series(m, 9)
            h = [a - b for a, b in zip(m, sg)]
            zones, atr = _sr_zones(cs)
            out = {"rsi": r, "rsi_prev": rp, "hist": h[-1], "hist_prev": h[-3], "macd": m[-1], "zones": zones,
                   "atr": atr, "last": cs[-4:]}
    except Exception as e:
        print(f"[chart_read] {name}: {e!r}")
    _chart_read_cache[name] = (now, out)
    return out


def flip_chart_part(name, call_sign, spot, line):
    """Points (-15..+25) the chart adds to the flip score, plus (weight, driver text, spoken words) tuples."""
    cr = chart_read(name)
    if not cr or not spot or not line:
        return 0.0, [], {}
    pts, why = 0.0, []
    dec = 4 if name == "XRP" else 2
    atr = cr["atr"] or spot * 0.0005
    last = cr["last"]
    # --- support / resistance: the zone that defends the call (between price and the line) and the ceiling / floor in its way
    for z in cr["zones"]:
        defends = (not z["r"]) if call_sign > 0 else z["r"]       # support under an UP call, resistance over a DOWN call
        z_txt = f'{fmt_price(z["lo"], dec)}-{fmt_price(z["hi"], dec)}'
        between = (line < z["mid"] < spot) if call_sign > 0 else (spot < z["mid"] < line)
        if defends and between and z["n"] >= 2:
            held_now = any((b[3] <= z["hi"] and b[4] > z["hi"]) if call_sign > 0 else (b[2] >= z["lo"] and b[4] < z["lo"]) for b in last)
            v = -min(12.0, 4 + 2 * z["n"] + (4 if held_now else 0))
            pts += v
            why.append((v, f'{"support" if call_sign > 0 else "resistance"} {z_txt} {"held" if call_sign > 0 else "rejected"} {z["n"]}x between price and the line'
                           + ((" (just held again)" if call_sign > 0 else " (just rejected again)") if held_now else ""),
                        f'{"support" if call_sign > 0 else "resistance"} holding above the line' if call_sign > 0 else "resistance holding below the line"))
        elif defends and not between:
            # the defending zone was just broken toward the line
            broke = any((b[4] < z["lo"]) if call_sign > 0 else (b[4] > z["hi"]) for b in last[-2:]) and z["n"] >= 2 \
                and abs(spot - z["mid"]) <= 1.5 * atr
            if broke:
                v = min(12.0, 5 + 1.5 * z["n"])
                pts += v
                why.append((v, f'{"support" if call_sign > 0 else "resistance"} {z_txt} just broke ({z["n"]}x level)',
                            f'{"support" if call_sign > 0 else "resistance"} just broke'))
        elif not defends and abs(spot - z["mid"]) <= 2.5 * atr:
            # the opposing zone near price: a fresh rejection there (wick in, close back out) turns price back toward the line
            rej = any((b[2] >= z["lo"] and b[4] < z["lo"]) if call_sign > 0 else (b[3] <= z["hi"] and b[4] > z["hi"]) for b in last)
            if rej:
                v = min(14.0, 6 + 2 * z["n"])
                pts += v
                why.append((v, f'{"rejected at resistance" if call_sign > 0 else "bounced off support"} {z_txt} ({z["n"]}x level)',
                            "rejected at resistance" if call_sign > 0 else "bounced off support"))
            elif z["n"] >= 2 and abs(spot - z["mid"]) <= 1.2 * atr:
                pts += 3
                why.append((3, f'{"ceiling" if call_sign > 0 else "floor"} right {"above" if call_sign > 0 else "below"} at {z_txt} ({z["n"]}x)', ""))
    # --- RSI (1-minute, Wilder 14)
    r, rp = cr["rsi"], cr["rsi_prev"]
    if r is not None:
        stretched = r >= 70 if call_sign > 0 else r <= 30
        if stretched:
            v = _lerp(abs(r - 50), 20, 35, 4, 10)
            pts += v
            why.append((v, f'RSI {r:.0f} {"overbought" if call_sign > 0 else "oversold"}', f'R S I {"overbought" if call_sign > 0 else "oversold"}'))
        if rp is not None and (rp - r) * call_sign >= 6:
            pts += 4
            why.append((4, f'RSI turning {"down" if call_sign > 0 else "up"} ({rp:.0f} -> {r:.0f})', f'R S I turning {"down" if call_sign > 0 else "up"}'))
    # --- MACD (12,26,9) histogram
    h, hp = cr["hist"], cr["hist_prev"]
    rel = abs(h) / spot
    if rel >= 0.000005:
        against = (h * call_sign) < 0
        growing = abs(h) > abs(hp) and (h * hp) > 0
        if against:
            v = _lerp(rel, 0.000005, 0.00008, 2, 8) + (2 if growing else 0)
            pts += v
            why.append((v, f'MACD {"bearish" if call_sign > 0 else "bullish"}{" and widening" if growing else ""}',
                        f'MACD {"bearish" if call_sign > 0 else "bullish"}'))
        elif growing:
            pts -= 3
            why.append((-3, f'MACD backing the call', ""))
    pts = max(-15.0, min(25.0, pts))
    return pts, why, {"rsi": r, "hist": h}


def flip_risk_core(name, call_sign, spot, line, seconds_left, elapsed=None, crosses=0, events=None, ticker=None):
    """call_sign: +1 the call is UP, -1 DOWN. Returns {"score", "tier", "cls", "parts", "drivers", "opp_share", "toward"}."""
    if not spot or not line or call_sign not in (1, -1):
        return None
    parts, drivers = {}, []
    usd = lambda v: _usd_short(abs(v))
    # ---- 1. opposing momentum
    win = {}
    if name in _flow.ASSETS:
        for w in (10, 30, 60):
            try:
                win[w] = _flow.HUB.window_detail(name, w)
            except Exception:
                pass
    shares, wts = [], []
    for w, wt in ((10, 0.30), (30, 0.45), (60, 0.25)):
        x = win.get(w)
        if x and x.get("pct") is not None and (x["buy"] + x["sell"]) > 0:
            opp = (1 - x["pct"]) if call_sign > 0 else x["pct"]
            shares.append(opp * wt)
            wts.append(wt)
    opp_share = sum(shares) / sum(wts) if wts else None
    mom = _lerp(opp_share, 0.45, 0.80, 0, 30) if opp_share is not None else 0.0
    net_against = 0.0
    for w in (30, 60):
        x = win.get(w)
        if x:
            net_against += ((x["sell"] - x["buy"]) if call_sign > 0 else (x["buy"] - x["sell"]))
    net_qty = 0.0
    x30 = win.get(30)
    if x30:
        net_qty = (x30["sell_qty"] - x30["buy_qty"]) if call_sign > 0 else (x30["buy_qty"] - x30["sell_qty"])
    sym = {a["name"]: a["symbol"] for a in DASHBOARD_ASSETS}.get(name)
    toward = False
    fast_move = False
    ago = None
    if sym:
        ticks = get_tick_history(sym)
        if ticks:
            cut = time.time() - 30
            older = [px for t, px in ticks if t <= cut]
            ago = older[-1] if older else ticks[0][1]
            # moving at the line = an UP call losing ground (price falling) / a DOWN call losing ground (price rising)
            toward = ((spot - ago) * call_sign) < -(line * 0.00005)
            # 2026-10-23 (b): "price / tape shifting quickly" = 0.03%+ toward the line in 30s (about $30 on BTC)
            fast_move = ((spot - ago) * call_sign) < -(line * 0.0003)
    thr = FLIP_OPP_DELTA_USD.get(name, 1e12)
    if net_against > 0 and toward:
        mom += _lerp(net_against, thr * 0.5, thr * 2, 0, 10)
    parts["momentum"] = round(mom, 1)
    if opp_share is not None and opp_share > 0.5:
        opp_word = "sellers" if call_sign > 0 else "buyers"
        coin_txt = f' ({"-" if call_sign > 0 else "+"}{abs(net_qty):,.{2 if name == "BTC" else 0}f} {name} 30s)' if net_qty > 0 else ""
        drivers.append((mom, f'{opp_word} {opp_share:.0%} of 10s/30s/1m flow{coin_txt}' + (" &amp; price moving at the line" if toward else " (absorbed - price holding)")))
    # ---- 2. cushion + crosses
    dist = (spot - line) / line * 100 * call_sign          # + = on the call's side, % of the line
    wrong_side = dist < 0
    cush = 0.0 if wrong_side else _lerp(-dist, -0.20, -0.02, 0, 25)
    if not wrong_side:
        for lo_, hi_, a_, b_ in ((0.15, 0.20, 5, 0), (0.10, 0.15, 12, 5), (0.05, 0.10, 20, 12), (0.02, 0.05, 25, 20)):
            if lo_ <= dist < hi_:
                cush = _lerp(dist, lo_, hi_, a_, b_)
        if dist < 0.02:
            cush = 25.0
        if dist >= 0.20:
            cush = 0.0
    cx = 0.0
    for ev in (events or []):
        recent = elapsed is not None and (elapsed - ev[0]) <= 180
        cx += 6.5 if recent else 5.0
    cx = min(15.0, cx) if events else min(15.0, 5.0 * (crosses or 0))
    parts["cushion"], parts["crosses"] = round(cush, 1), round(cx, 1)
    dec = 4 if name == "XRP" else 2
    gap_usd = abs(spot - line)
    if wrong_side:
        drivers.append((75, f'price already on the WRONG side of the line ({fmt_price(gap_usd, dec)} / {abs(dist):.3f}%)'))
    elif cush >= 12:
        drivers.append((cush, f'thin cushion: +{fmt_price(gap_usd, dec)} ({dist:.3f}%) from the line'))
    if crosses:
        drivers.append((cx, f'{crosses} line cross{"es" if crosses != 1 else ""} - contested level'))
    # ---- 3. order book walls (every exchange that reports its book)
    book = 0.0
    try:
        sm = _flow.HUB.summary(name) if name in _flow.ASSETS else {}
    except Exception:
        sm = {}
    bp, bn = sm.get("book_pct"), sm.get("book_n") or 0
    if bp is not None:
        sup = bp if call_sign > 0 else 1 - bp
        opp = 1 - sup
        if opp > 0.52:
            book = _lerp(opp, 0.52, 0.65, 2, 20)
            drivers.append((book, f'{opp:.0%} {"ask" if call_sign > 0 else "bid"} walls pressing on the call ({bn} books)'))
        elif sup > 0.52:
            book = -_lerp(sup, 0.52, 0.65, 2, 15)
            drivers.append((book, f'{sup:.0%} {"bid" if call_sign > 0 else "ask"} walls defending ({bn} books)'))
    parts["book"] = round(book, 1)
    # ---- 4. chart: support / resistance holds + rejections, RSI, MACD (2026-10-23)
    chart, cwhy, _cread = flip_chart_part(name, call_sign, spot, line)
    parts["chart"] = round(chart, 1)
    say = []
    for w_, txt_, sp_ in cwhy:
        drivers.append((w_, txt_))
        if sp_ and w_ > 0:
            say.append((w_, sp_))
    if opp_share is not None and opp_share >= 0.6 and mom >= 12:
        say.append((mom, f'{"sellers" if call_sign > 0 else "buyers"} in control'))
    # ---- pace + time
    pace = None
    try:
        vg = _flow.HUB.volume_gauge(name) if name in _flow.ASSETS else None
        if vg and vg.get("median"):
            pace = vg["total"] / vg["median"]
    except Exception:
        pass
    raw = mom + cush + cx + book + chart
    pf = min(1.35, max(0.75, pace)) if pace else 1.0
    score = max(0.0, raw) * pf
    tf = 1.0
    if seconds_left is not None and not wrong_side:
        if seconds_left <= 90 and dist > 0.12:
            tf = max(0.35, seconds_left / 90)
        try:
            tw = twap_lock(name, {"ticker": ticker, "target_price": line, "spot_price": spot}) if ticker else None
        except Exception:
            tw = None
        if tw and not tw["final"] and ((tw["side"] == "UP") == (call_sign > 0)):
            # final minute: how hard is it for the remaining seconds to drag the 60s average across?
            tf = min(tf, 0.3 if tw["locked"] else _lerp(tw["reach"] or 0, 0.0, 0.25, 1.0, 0.45))
            drivers.append((0, f'60s settlement avg {fmt_price(tw["avg"], dec)} - {"LOCKED" if tw["locked"] else "still reachable"}'))
    score *= tf
    if wrong_side:
        score = max(score, 75.0 + min(20.0, abs(dist) * 100))
    score = max(0.0, min(99.0, score))
    tier, cls = "LOW", "up"
    for lim, t_, c_ in FLIP_TIERS:
        if score <= lim:
            tier, cls = t_, c_
            break
    if pace:
        drivers.append((0, f'market pace {pace:.1f}x normal'))
    return {"score": score, "tier": tier, "cls": cls, "parts": parts, "pace": pace, "opp_share": opp_share,
            "toward": toward, "wrong_side": wrong_side, "dist_pct": dist,
            "say": [t for _w, t in sorted(say, key=lambda z: -z[0])][:2],
            "shift": bool(fast_move and opp_share is not None and opp_share >= 0.55),
            "drivers": [t for _w, t in sorted(drivers, key=lambda z: -abs(z[0]))]}


# ---- 10-second rule (2026-10-20, user request): a one-second burst must not throw the radar from 10% to 42%. The score shown
# is the LOWEST raw score of the last 10 seconds, so it can only climb as far as pressure has held for 10 straight seconds,
# and drops straight away when pressure eases. Under 10 seconds of readings it never shows more than 20%.
FLIP_SUSTAIN_S = 10
FLIP_FREE_PCT = 20.0
_flip_hist = {}          # (asset, ticker, call_sign) -> deque of (ts, raw score)


def flip_risk_sustained(name, call_sign, spot, line, seconds_left, elapsed=None, crosses=0, events=None, ticker=None):
    fr = flip_risk_core(name, call_sign, spot, line, seconds_left, elapsed, crosses, events, ticker)
    if not fr:
        return fr
    now = time.time()
    key = (name, ticker, call_sign)
    h = _flip_hist.get(key)
    if h is None:
        h = _flip_hist[key] = collections.deque()
        for k in [k for k in _flip_hist if k[0] == name and k != key and k[1] != ticker]:
            _flip_hist.pop(k, None)               # old rounds
    h.append((now, fr["score"]))
    while h and now - h[0][0] > FLIP_SUSTAIN_S + 5:
        h.popleft()
    win = [sc for t, sc in h if now - t <= FLIP_SUSTAIN_S]
    covered = (now - h[0][0]) >= FLIP_SUSTAIN_S - 1
    raw = fr["score"]
    shown = min(win) if covered else min(raw, FLIP_FREE_PCT, min(win))
    fr["raw"] = raw
    fr["score"] = shown
    fr["held"] = covered
    tier, cls = "LOW", "up"
    for lim, t_, c_ in FLIP_TIERS:
        if shown <= lim:
            tier, cls = t_, c_
            break
    fr["tier"], fr["cls"] = tier, cls
    return fr


# ---------------------------------------------------------------- REVERSAL CALLS (2026-10-20, user request)
# "Don't be scared to call the currently losing side if the RSI data and other factors support it." When the composite
# flip score says the side price is on now is in trouble AND RSI + momentum point the other way, the early / sealed call
# goes to the LOSING side (that is where the 3x+ Kalshi payouts are). Graded like every other call, and tracked
# separately in the round history so you can see whether these actually pay.
REV_RECORD_SINCE = 1792708800      # 2026-10-22 22:40 UTC: reversal W/L reset when the flip-history system went live
REVERSAL_MIN_DOG_PRICE = 0.30   # the underdog must cost 30c+ (pays ~3.3x at most) - long shots lost too often
REVERSAL_MIN_SCORE = 55         # composite flip risk of the current favorite must be HIGH
REVERSAL_MIN_VOTES = 3          # at least 3 of: RSI stretched, flow against, candles against, trend against, price moving at the line
REVERSAL_RSI_HI, REVERSAL_RSI_LO = 68, 32


def reversal_check(name, spot, line, seconds_left, elapsed, line_stats, rsi_multi, sig, kalshi_yes, ticker=None, stage=None):
    """None, or {"call", "tier", "why", "score", "votes", "payout"} - call the UNDERDOG.
    2026-10-22 (d, user: "the reversal/underdog doesn't have to call a reversal every round - use a way more effective
    system based on the history of all the flips in the last month"): ONE system now - the backtest's flip-history table.
    Every 4:00 / 8:00 moment of the last 30 days is filed by underdog price, distance to the line, crosses so far and how
    many reads turned; a reversal fires only when that exact situation's real history says the underdog wins 50%+ AND
    beats its own price by 8+ points, and only at a mark where the table also won on the newest rounds it never saw."""
    if not spot or not line or kalshi_yes is None:
        return None
    # 2026-10-23 (user: "the reversal thing was not helping"): the daily audit turns underdog calls off unless a flip signal
    # beats luck on rounds it never saw (30-day check: no rule did, and the old table fired 0 times on unseen rounds)
    try:
        import flip_audit as _fa
        if not (_fa.decisions().get("reversal_on") or {}).get(stage or "sealed"):
            return None
    except Exception:
        return None
    try:
        _dec = _bt.decisions()
    except Exception:
        return None
    tab = (_dec.get("flip_tables") or {}).get(stage or "sealed")
    if not tab:
        return None
    f = {"kp": kalshi_yes, "dist": (spot - line) / line, "crosses": (line_stats or {}).get("crosses") or 0,
         "r1_tv": (rsi_multi or {}).get("rsi1"), "sig": sig or {}}
    fc = _bt.flip_call(tab, f)
    if not fc or fc["dog"] < REVERSAL_MIN_DOG_PRICE:
        return None
    pay = 1 / fc["dog"]
    why = (f"REVERSAL - flip history: the underdog won {fc['wins']} of {fc['n']} setups like this in the last 30 days "
           f"({fc['rate']:.0%} with recent days weighted) &middot; pays ~{pay:.1f}x")
    tier = "GOOD" if fc["rate"] - fc["dog"] >= 0.15 else "WEAK"
    return {"call": fc["call"], "tier": tier, "why": why, "score": None, "votes": [], "payout": round(pay, 2), "kp": fc["dog"],
            "hist": fc}


def _reversal_watch_html(name, d):
    """Inside the Flip Radar: shows ONLY when the flip history makes this round interesting - REVERSAL READY when the
    history rule fires, or a quiet 'underdog setup' note when similar rounds flipped 40%+ of the time. Most rounds: nothing."""
    try:
        spot, line, kp = d.get("spot_price"), d.get("target_price"), _live_kp(d)
        if not (spot and line) or kp is None:
            return ""
        ls = d.get("line_stats") or {}
        rm = d.get("rsi_multi") or {}
        stage = "sealed" if ((d.get("stage_calls") or {}).get("early") or {}).get("call") else "early"
        rv = reversal_check(name, spot, line, d.get("seconds_left"), d.get("elapsed_seconds"), ls, rm, d.get("stage_sig"), kp,
                            d.get("ticker"), stage=stage)
        if rv:
            h = rv["hist"]
            return (f'<div class="rv-watch rv-ready"><b><i class=ico data-i=reversal></i> REVERSAL READY</b> &middot; '
                    f'{"UP" if rv["call"] == "YES" else "DOWN"} &middot; won {h["wins"]}/{h["n"]} like this &middot; pays ~{rv["payout"]:.1f}x</div>')
        tab = ((_bt.decisions().get("flip_tables_all") or {}).get(stage)) or {}
        f = {"kp": kp, "dist": (spot - line) / line, "crosses": ls.get("crosses") or 0, "r1_tv": rm.get("rsi1"), "sig": d.get("stage_sig") or {}}
        info = _bt.flip_cell_info(tab, f)
        if info and info["n"] >= _bt.FLIP_MIN_N and info["rate"] >= 0.40:
            return (f'<div class="rv-watch rv-near"><b><i class=ico data-i=reversal></i> UNDERDOG SETUP</b> '
                    f'{"UP" if info["call"] == "YES" else "DOWN"} &middot; flipped {info["rate"]:.0%} of {info["n"]} like this '
                    f'<span class="hint">(not enough to call)</span></div>')
        return ""
    except Exception:
        return ""


@_never_break
def build_flip_radar(name, d):
    """FLIP RADAR tile: the composite flip-risk score for the call on screen (sealed, else early, else the side price is on
    now), its tier, and the exact drivers. Kalshi's own odds are shown underneath only as a reference."""
    key, call = _stage_ref(d)
    which = "the sealed call" if key == "sealed" else ("the early call" if key == "early" else None)
    spot, line = d.get("spot_price"), d.get("target_price")
    if call not in ("YES", "NO"):
        call = d.get("locked_call") if d.get("locked_call") in ("YES", "NO") else None
        which = which or ("the bot's call" if call else None)
    if call is None and spot and line:
        call = "YES" if spot >= line else "NO"
        which = "the side price is on now"
    if not (spot and line and call):
        return '<div class="rs-tile flip-radar"><div class="rs-title">FLIP RADAR</div><div class="fr-big flat">--</div></div>'
    ls = d.get("line_stats") or {}
    sc_ = ((d.get("stage_calls") or {}).get(key) or {}) if key else {}
    csign = 1 if call == "YES" else -1
    rev_waiting = bool(sc_.get("reversal")) and (spot - line) * csign < 0
    if rev_waiting:
        # a REVERSAL call starts on the losing side on purpose - so show how likely the cross it needs is (the flip risk of
        # the side price is on now), not a scary "CRITICAL, it's losing"
        fv = flip_risk_sustained(name, -csign, spot, line, d.get("seconds_left"), d.get("elapsed_seconds"),
                                 ls.get("crosses") or 0, ls.get("events"), d.get("ticker"))
        if fv:
            pc = fv["score"]
            cls_ = "up" if pc >= 46 else ("warn" if pc >= 21 else "down")
            lvl = "ON TRACK" if pc >= 46 else ("BUILDING" if pc >= 21 else "STALLED")
            return (f'<div class="rs-tile flip-radar"><div class="rs-title">FLIP RADAR &middot; REVERSAL</div>'
                    f'<div class="fr-big {cls_}">{pc:.0f}% <span>{lvl}</span></div>'
                    f'<div class="fr-track2"><i class="{cls_}" style="width:{min(100, pc):.0f}%"></i></div>'
                    f'<div class="fr-txt">Chance price crosses back to {"UP" if call == "YES" else "DOWN"} - the cross this reversal needs</div>'
                    + (f'<!--OWNER--><div class="fr-txt hint">{" &middot; ".join(fv["drivers"][:3])}</div><!--/OWNER-->' if fv["drivers"] else "")
                    + f'<div class="rv-watch rv-ready"><b><i class=ico data-i=reversal></i> REVERSAL CALLED</b> - '
                      f'{"UP" if call == "YES" else "DOWN"}{(" &middot; pays ~" + format(sc_["rev_payout"], ".1f") + "x") if sc_.get("rev_payout") else ""}</div>'
                    + '</div>')
    fr = flip_risk_sustained(name, csign, spot, line, d.get("seconds_left"), d.get("elapsed_seconds"),
                             ls.get("crosses") or 0, ls.get("events"), d.get("ticker"))
    if not fr:
        return '<div class="rs-tile flip-radar"><div class="rs-title">FLIP RADAR</div><div class="fr-big flat">--</div></div>'
    pct, level, cls = fr["score"], fr["tier"], fr["cls"]
    # 2026-10-23 (audit, 30 days / 2,840 rounds): the market's own price predicts flips as well as anything BRAIN reads (flip
    # history error 0.1497 vs market 0.1491). So the radar never shows LESS than the market's odds on the other side - it can
    # only add to them when the live reads see more pressure than the market has priced.
    _kpm = d.get("kalshi_price")
    if _kpm is not None:
        _mkt = ((1 - _kpm) if call == "YES" else _kpm) * 100
        if _mkt > pct:
            pct = min(99.0, _mkt)
            fr["drivers"] = [f"market odds on the other side: {_mkt:.0f}%"] + fr["drivers"]
            for lim, t_, c_ in FLIP_TIERS:
                if pct <= lim:
                    level, cls = t_, c_
                    break
    rm = d.get("rsi_multi") or {}
    r1 = rm.get("rsi1")
    extra = []
    if _ENG.recent_kind(name, ("stoprun",), side=("sell" if call == "YES" else "buy"), within=240):
        extra.append("fake breakout against it")
    drv = extra + fr["drivers"][:4]
    kp = d.get("kalshi_price")
    kal = ""
    if kp is not None:
        k_opp = (1 - kp) if call == "YES" else kp
        kal = f'<div class="fr-txt hint">Market odds on the other side: {k_opp * 100:.0f}%</div>'
    spike = ""
    if fr.get("raw") is not None and fr["raw"] - pct >= 10:
        spike = f'<div class="fr-txt hint">spiking to {fr["raw"]:.0f}%</div>'
    p = fr["parts"]
    tip = (f'momentum {p["momentum"]:+.0f} &middot; cushion {p["cushion"]:+.0f} &middot; crosses {p["crosses"]:+.0f} &middot; '
           f'book walls {p["book"]:+.0f} &middot; chart {p.get("chart", 0):+.0f}' + (f' &middot; pace {fr["pace"]:.2f}x' if fr.get("pace") else ""))
    _cname = key or ("bot" if which == "the bot's call" else "none")
    marker = (f'<span class="flip-chance-value" data-flip-src="radar" data-flip-chance-key="{name}::{d.get("ticker", "")}{("::" + key) if key else ""}" '
              f'data-flip-chance-pct="{pct:.2f}" data-k-opp="{(((1 - kp) if call == "YES" else kp) if kp is not None else -1):.3f}" '
              f'data-call="{call}" data-call-name="{_cname}" '
              f'data-kup="{kp if kp is not None else -1:.3f}" data-left="{int(d.get("seconds_left") or 0)}" '
              f'data-above="{1 if spot >= line else 0}" data-shown="{pct:.0f}" data-tier="{level}" data-micro="{d.get("micro_dir") or ""}" data-shift="{1 if fr.get("shift") else 0}" '
              f'data-crosses="{int(ls.get("crosses") or 0)}" style="display:none;"></span>')
    _early_in = bool(((d.get("stage_calls") or {}).get("early") or {}).get("call"))     # 2026-10-22 (user)
    return (f'<div class="rs-tile flip-radar"><div class="rs-title">FLIP RADAR</div>'
            f'<div class="fr-big {cls}">{pct:.0f}% <span>{level}</span></div>'
            f'<div class="fr-track2"><i class="{cls}" style="width:{min(100, pct):.0f}%"></i></div>'
            f'<div class="fr-txt">chance <b class="{"up" if call == "YES" else "down"}">{_ARROW_UP if call == "YES" else _ARROW_DN}</b> flips <span class="hint">({which.replace("the ", "")})</span></div>'
            + '<!--OWNER-->' + (f'<div class="fr-txt"><i class=ico data-i=warn></i> {" &middot; ".join(drv)}</div>' if drv and pct > 20 else
               f'<div class="fr-txt hint">{" &middot; ".join(drv) if drv else "no pressure against it right now"}</div>')
            + f'<div class="fr-txt hint">{_html_attr(tip).replace("&amp;middot;", "&middot;")}</div><!--/OWNER-->'
            + (f'<div class="fr-txt fr-why"><b>Why:</b> {" &middot; ".join(drv[:3])}</div>' if drv and (pct >= 40 or fr.get("shift")) else "")
            + f'{_flip_why(name, d, call, pct)}{spike}{kal}{_flips_4h(name)}{_reversal_watch_html(name, d) if _early_in else ""}{marker}</div>')


_ARROW_UP = '<svg class="v-arr" viewBox="0 0 20 20" aria-label="up"><path d="M10 3 L17.5 14 H2.5 Z" fill="currentColor"/></svg>'
_ARROW_DN = '<svg class="v-arr" viewBox="0 0 20 20" aria-label="down"><path d="M10 17 L17.5 6 H2.5 Z" fill="currentColor"/></svg>'


def _flips_4h(name):
    """2026-10-22 (user): teach with history - how many of the last 4 hours of rounds flipped (price on one side of the line
    at 4:00, settled on the other) and how many line crosses there were."""
    try:
        now = time.time()
        rs = [r for r in (_rounds.get(name) or []) if (lambda t: t and now - t.timestamp() <= 4 * 3600)(_window_close_utc(r.get("ticker")))]
        if not rs:
            return ""
        flips = 0
        for r in rs:
            pth = r.get("path") or []
            at4 = next((p_[1] for p_ in pth if p_[0] >= 240), None)
            act = r.get("actual")
            if at4 is not None and act in ("YES", "NO") and abs(at4) > 1e-9 and ((at4 > 0) != (act == "YES")):
                flips += 1
        crosses = sum(r.get("crosses", 0) for r in rs)
        return (f'<div class="fr-txt fr-hist">Last 4 hrs: <b>{flips}</b> of {len(rs)} round{"s" if len(rs) != 1 else ""} flipped after 4:00 '
                f'&middot; {crosses} line cross{"es" if crosses != 1 else ""}</div>')
    except Exception:
        return ""


def _flip_why(name, d, call, pct):
    """2026-10-22 (user): show WHY the flip chance is rising - the biggest order working against the call right now:
    a resting wall in the book, or big orders that just hit (whale / pile-in / sweep)."""
    if pct is None or pct < 15 or call not in ("YES", "NO"):
        return ""
    against = "sell" if call == "YES" else "buy"
    dec = 4 if name == "XRP" else 2
    best = None
    try:
        bw = d.get("book_walls") or {}
        w = bw.get("ask_wall") if against == "sell" else bw.get("bid_wall")
        if w and w[1]:
            best = (w[1], f'<b>{_usd_short(w[1])}</b> {against} wall waiting at {fmt_price(w[0], dec)} '
                          f'({w[2] * 100:.2f}% {"above" if against == "sell" else "below"} the price)')
    except Exception:
        pass
    try:
        for a in _ENG.alerts_for(name, max_age=180, limit=40):
            if a.get("side") != against or not a.get("usd") or a.get("kind") not in ("whale", "amass", "sweep", "absorbed", "moved", "burst", "liq"):
                continue
            if best is None or a["usd"] > best[0]:
                lab = {"whale": f"{against} order just went through", "amass": f"of {against} orders piled in (30 s)",
                       "sweep": f"{against} order just pushed the price", "absorbed": "order got eaten against it",
                       "moved": f"{against} wall moved in on the price", "burst": f"more {'selling' if against == 'sell' else 'buying'} than the other side (10 s)",
                       "liq": "of forced " + ("selling" if against == "sell" else "buying")}.get(a["kind"], "order against it")
                best = (a["usd"], f'<b>{_usd_short(a["usd"])}</b> {lab}')
    except Exception:
        pass
    if not best:
        return ""
    return f'<div class="fr-why"><span>Why it&#39;s rising:</span> {best[1]}</div>'


def _mmss_words(sec):
    m_, s_ = divmod(max(0, int(sec)), 60)
    return (f"{m_} min {s_} sec" if m_ else f"{s_} sec")


