@_never_break
def build_time_until_call(name, d):
    """Top-row countdown to the next call: 'EARLY CALL coming in 2 min 31 sec', then 'SEALED CALL coming in ...';
    once both are in, the time to the next round."""
    el = int(d.get("elapsed_seconds") or 0)
    left = int(d.get("seconds_left") or 0)
    sc = d.get("stage_calls") or {}
    nxt = None
    for key, mark, lab, mk in STAGE_CALLS:
        if key not in sc:
            nxt = (key, mark, lab, mk)
            break
    if nxt:
        key, mark, lab, mk = nxt
        wait = mark - el
        if wait > 0:
            _to = int(time.time()) + wait
            t = f'<span data-to="{_to}">{wait // 60}:{wait % 60:02d}</span>'
            what = f'<b>{lab.upper()}</b> coming in <span data-to="{_to}" data-to-fmt="words">{_mmss_words(wait)}</span>'
        else:
            t, what = "NOW", f"<b>{lab.upper()}</b> - waiting for a clear lean"
        cls = "tuc-early" if key == "early" else "tuc-sealed"
    else:
        _to = f' data-to="{d["close_epoch"]:.0f}"' if d.get("close_epoch") else ""
        t = f"<span{_to}>{left // 60}:{left % 60:02d}</span>"
        what = 'both calls are in'
        cls = "tuc-done"
    # 2026-10-22 (user): after the sealed call the box counts down to the next round
    return (f'<div class="callbox tuc {cls}"><div class="tuc-lbl">{"TIME UNTIL NEXT ROUND" if cls == "tuc-done" else "TIME UNTIL CALL"}</div><div class="tuc-time">{t}</div>'
            f'<div class="tuc-what">{what}</div></div>')


_MKT_TFS = (("1m", "1m"), ("5m", "5m"), ("15m", "15m"), ("1h", "1h"), ("1d", "1D"))
_MKT_SPAN = {"1m": "20 min", "5m": "100 min", "15m": "5 hours", "1h": "20 hours", "1d": "20 days"}


@_never_break
def build_market_box(name):
    """Small market-trend box above the coin name: one button per timeframe, coloured by that timeframe's own read -
    green = bullish, pink = bearish, grey = neutral. Tap one for the detail (the % move over its last 20 candles)."""
    if _mtf is None:
        return ""
    sym = {a["name"]: a["symbol"] for a in DASHBOARD_ASSETS}.get(name)
    res = _mtf.results.get(sym) or {}
    win = _mtf.windows.get(sym) or {}
    btns, panes = [], []
    for tf, lab in _MKT_TFS:
        a = res.get(tf) or {}
        bias = a.get("bias", "neutral")
        cls = "bull" if bias == "bullish" else ("bear" if bias == "bearish" else "neut")
        cs = win.get(tf) or []
        chg = ((cs[-1][4] / cs[-21][4] - 1) * 100) if len(cs) >= 21 and cs[-21][4] else None
        word = {"bull": "BULLISH", "bear": "BEARISH", "neut": "NEUTRAL"}[cls]
        btns.append(f'<button class="{cls}" data-mkt="{name}|{tf}" onclick="setMkt(&#39;{name}&#39;,&#39;{tf}&#39;)">{lab}</button>')
        panes.append(f'<div class="mkt-pane" data-mkt-pane="{name}|{tf}"><b class="{"up" if cls == "bull" else ("down" if cls == "bear" else "flat")}">'
                     f'{lab} {word}</b>' + (f' &middot; {chg:+.2f}% over {_MKT_SPAN[tf]}' if chg is not None else "") + '</div>')
    return f'<div class="mkt" data-mkt-box="{name}"><div class="mkt-btns">{"".join(btns)}</div>{"".join(panes)}</div>'


@_never_break
def build_cross_box(name, d):
    """Small box like the RSI one: how many times price crossed the line this round (15-second rule), colour-coded."""
    ls = d.get("line_stats") or {}
    if not ls:
        return '<div class="rs-tile lx-box"><div class="rs-title">LINE CROSSES</div><div class="lx-num flat">--</div><div class="lx-zone flat">waiting</div></div>'
    n = ls.get("crosses", 0)
    cls, zone = ("lx-clean", "CLEAN") if n <= 1 else (("lx-some", "SOME CHOP") if n == 2 else ("lx-chop", "CHOPPY"))
    # 2026-10-22: the backtest's market-favorite win rate for each cross count (21 days, 1-minute closes) under the box
    _chk = ""
    try:
        _cc = ((_bt.load_saved() or {}).get("cross_check") or {}).get("sealed") or {}
        if _cc:
            _bits = [f'{c}{"+" if c == "4" else ""}: {x["fav_win"] * 100:.0f}%' for c, x in _cc.items() if x["n"] >= 15]
            if _bits:
                _chk = f'<div class="lx-sub hint" title="How often the market favorite won at 8:00, by line crosses so far (backtest, 1-minute closes)">favorite won: {" &middot; ".join(_bits)}</div>'
    except Exception:
        pass
    # 2026-10-23 (user): no cross for 5+ minutes -> say what that means: has the market DECIDED, is it STABILIZING, or is it just
    # sitting on the line - plus how much it is moving (volatility from the last 5 minutes of the price path)
    _quiet = ""
    try:
        el = d.get("elapsed_seconds")
        ev = ls.get("events") or []
        path = ls.get("path") or []
        if el is not None and path:
            since = el - (ev[-1][0] if ev else 0)
            if since >= 300:
                recent = [x[1] for x in path if x[0] >= el - 300] or [path[-1][1]]
                swing = max(recent) - min(recent)             # % of the line, last 5 min
                dist = path[-1][1]
                way = "UP" if dist > 0 else "DOWN"
                vol, vcls = (("LOW", "up") if swing < 0.05 else (("MEDIUM", "warn") if swing < 0.15 else ("HIGH", "down")))
                if abs(dist) >= 0.06:
                    verdict = f"MARKET DECIDED &middot; holding {way}"
                elif abs(dist) >= 0.02:
                    verdict = f"STABILIZING {way}"
                else:
                    verdict = "SITTING ON THE LINE"
                _quiet = (f'<div class="lx-quiet"><b>{verdict}</b><span>No cross for {int(since // 60)} min &middot; volatility '
                          f'<b class="{vcls}">{vol}</b></span></div>')
    except Exception:
        _quiet = ""
    return (f'<div class="rs-tile lx-box {cls}"><div class="rs-title">LINE CROSSES</div><div class="lx-num">{n}</div>'
            f'<div class="lx-zone">{zone}</div><div class="lx-sub"><i class=va-u></i> {ls.get("up", 0)} up &middot; <i class=va-d></i> {ls.get("down", 0)} down</div>{_quiet}{_chk}</div>')


@_never_break
def build_round_strip(name, d):
    # 2026-10-22 (user): RSI + line crosses share one square; the streak tile moved up next to "time until call"
    return (f'<div class="round-strip calls-row">{build_stage_box(name, d, "early")}{build_stage_box(name, d, "sealed")}'
            f'{build_flip_radar(name, d)}<div class="rs-tile rsi-lx"><div class="lx-mkt lx-mkt-top" tabindex="0" title="Tap or hover for the trend details"><div class="lx-mkt-lbl">MARKET TREND</div>{build_market_box(name)}</div>{build_rsi_box(name, d)}{build_cross_box(name, d)}</div></div>')


def _streak_stats(results):
    cur_t, cur_n = None, 0
    for r in reversed(results):
        if cur_t is None:
            cur_t, cur_n = r, 1
        elif r == cur_t:
            cur_n += 1
        else:
            break
    best_w = best_l = run = 0
    prev = None
    for r in results:
        run = run + 1 if r == prev else 1
        prev = r
        if r:
            best_w = max(best_w, run)
        else:
            best_l = max(best_l, run)
    return cur_t, cur_n, best_w, best_l


# ---------------------------------------------------------------- WIN RATE BADGE + ROUND HISTORY (2026-10-20)
# Reads the SAME saved history (data_cache/kalshi_dashboard_history.json, up to HISTORY_CAP rounds) the streak tile and
# scoreboard use - nothing is reset or re-counted, so the current streak simply carries on.
# 2026-10-20: auto-buy isn't in use, so the bot's own call record / streak is hidden everywhere (still saved in the
# history file - set SHOW_BOT_RECORD = True to bring it back).
SHOW_BOT_RECORD = False
WR_CALLS = {"sealed": ("Sealed 8:00", "sealed_correct", "sealed_call"),
            "early": ("Early 4:00", "early_correct", "early_call")}
if SHOW_BOT_RECORD:
    WR_CALLS["bot"] = ("Bot call", "correct", "call")


def _wr_rows(name, call):
    lab, field, cfield = WR_CALLS.get(call, WR_CALLS["sealed"])
    out = []
    for h in _history.get(name, []):
        if h.get(field) is None:
            continue
        t = _window_close_utc(h.get("ticker"))
        out.append({"t": t, "ok": bool(h[field]), "call": h.get(cfield), "actual": h.get("actual_side"),
                    "rev": bool(h.get(f"{call}_reversal")), "payout": h.get(f"{call}_payout"), "z80": h.get(f"{call}_zone80"),
                    "final": h.get("final_price"), "strike": h.get("strike"), "tier": h.get(f"{call}_tier") if call != "bot" else None,
                    "ticker": h.get("ticker"), "trend": h.get(f"{call}_trend")})
    return out


def _wr_stats(rows):
    res = [r["ok"] for r in rows]
    n, w = len(res), sum(res)
    if not n:
        return {"n": 0, "w": 0, "l": 0, "pct": None, "cur": (None, 0), "best": 0, "worst": 0}
    ct, cn, bw, bl = _streak_stats(res)
    return {"n": n, "w": w, "l": n - w, "pct": w / n * 100, "cur": (ct, cn), "best": bw, "worst": bl}


def winrate_badge_html(name):
    """The small top-right badge: current sealed-call streak (falls back to the early call), all-time win %, today."""
    call = "sealed"
    rows = [r for r in _wr_rows(name, call) if not r["rev"]]
    if not rows:
        call, rows = "early", [r for r in _wr_rows(name, "early") if not r["rev"]]
    st = _wr_stats(rows)
    if not st["n"]:
        return (f'<div class="wr-streak flat">--</div><div class="wr-sub">{name} &middot; no graded rounds</div>')
    ct, cn = st["cur"]
    et = ZoneInfo("America/New_York")
    day0 = dt.datetime.now(dt.timezone.utc).astimezone(et).replace(hour=0, minute=0, second=0, microsecond=0)
    today = [r["ok"] for r in rows if r["t"] and r["t"] > day0]
    fire = "<i class=ico data-i=flame></i> " if ct and cn >= 3 else ""
    return (f'<div class="wr-streak {"wr-w" if ct else "wr-l"}">{fire}{cn}{"W" if ct else "L"} <span>streak</span></div>'
            f'<div class="wr-sub"><b>{st["pct"]:.0f}%</b> win &middot; {st["n"]:,} rnds</div>'
            f'<div class="wr-sub">today {sum(today)}-{len(today) - sum(today)} &middot; {name} {WR_CALLS[call][0].split()[0].lower()}</div>')


def round_history_html(name, call="sealed", rng="all", limit=300):
    """The panel behind the badge: win rate / record / streaks for today, this week or all time, a day-by-day and a
    week-by-week table, and every graded round (newest first, 300 at a time)."""
    if name not in LIVE_ASSETS:
        name = next(iter(LIVE_ASSETS))
    call = call if call in WR_CALLS else "sealed"
    rows = _wr_rows(name, call)
    et = ZoneInfo("America/New_York")
    now_et = dt.datetime.now(dt.timezone.utc).astimezone(et)
    day0 = now_et.replace(hour=0, minute=0, second=0, microsecond=0)
    week0 = day0 - dt.timedelta(days=day0.weekday())
    since = {"today": day0, "week": week0}.get(rng)
    sel = [r for r in rows if since is None or (r["t"] and r["t"] > since)]
    st = _wr_stats([r for r in sel if not r["rev"]])            # main record: reversals have their own line below
    allst = _wr_stats([r for r in rows if not r["rev"]])

    def pct(x):
        return "-" if x is None else f'<span class="{"up" if x >= 60 else ("down" if x < 50 else "flat")}">{x:.1f}%</span>'
    ct, cn = allst["cur"]
    cur = (f'<b class="{"skw" if ct else "skl"}">{cn}{"W" if ct else "L"}</b>' if allst["n"] else "-")
    grid = (f'<div class="wr-grid"><div><b>{pct(st["pct"])}</b>win rate</div><div><b>{st["w"]}-{st["l"]}</b>won-lost</div>'
            f'<div><b>{st["n"]:,}</b>rounds</div><div><b>{cur}</b>current streak</div>'
            f'<div><b class="skw">{st["best"]}W</b>best run</div><div><b class="skl">{st["worst"]}L</b>worst run</div></div>')

    def bucket_table(keyfn, labfn, count, title):
        agg = {}
        for r in rows:
            if not r["t"]:
                continue
            k = keyfn(r["t"].astimezone(et))
            a = agg.setdefault(k, [0, 0])
            a[0 if r["ok"] else 1] += 1
        keys = sorted(agg, reverse=True)[:count]
        if not keys:
            return ""
        trs = "".join(f'<tr><td>{labfn(k)}</td><td>{agg[k][0]}-{agg[k][1]}</td><td>{pct(agg[k][0] / sum(agg[k]) * 100)}</td>'
                      f'<td>{sum(agg[k])}</td></tr>' for k in keys)
        return (f'<details class="wr-more"><summary>{title}</summary><table class="press-table"><tr><th>{title.split()[0]}</th>'
                f'<th>W-L</th><th>win %</th><th>rounds</th></tr>{trs}</table></details>')
    if call == "sealed":
        dl = [bool(h["decided_correct"]) for h in _history.get(name, []) if h.get("decided_correct") is not None
              and (since is None or ((_window_close_utc(h.get("ticker")) or now_et) > since))]
        if dl:
            grid += (f'<div class="wr-rev"><i class=ico data-i=clock></i> Late calls (price has decided): <b class="skw">{sum(dl)}W</b> - '
                     f'<b class="skl">{len(dl) - sum(dl)}L</b> ({sum(dl) / len(dl):.0%}) &middot; not part of the streak</div>')
    z8 = [r for r in sel if r.get("z80")]
    if z8:
        zw = sum(r["ok"] for r in z8)
        grid += (f'<div class="wr-rev"><i class=ico data-i=star></i> 80% setups (live): <b class="skw">{zw}W</b> - <b class="skl">{len(z8) - zw}L</b> '
                 f'({zw / len(z8):.0%})</div>')
    # 2026-10-22 (user: "learn from the losses ... especially during a trend"): the record with vs against the 1-min trend
    _tg = {}
    for r in sel:
        if r.get("trend") in (1, -1) and r.get("call") in ("YES", "NO"):
            k = "with" if (r["trend"] > 0) == (r["call"] == "YES") else "against"
            _tg.setdefault(k, []).append(r["ok"])
    if _tg:
        grid += ('<div class="wr-rev"><i class=ico data-i=radar></i> Calls vs the trend: ' + " &middot; ".join(
            f'{k} it <b class="skw">{sum(v)}W</b>-<b class="skl">{len(v) - sum(v)}L</b> ({sum(v) / len(v):.0%})'
            for k, v in sorted(_tg.items(), reverse=True)) + ' <span class="hint">- the history table learns from these</span></div>')
    rv = [r for r in sel if r.get("rev")]
    if rv:
        rw = sum(r["ok"] for r in rv)
        pays = [r["payout"] for r in rv if r.get("payout")]
        # $1 on every reversal at its locked price: a win returns payout x, a loss loses the $1
        ret = sum((r["payout"] - 1) if r["ok"] else -1 for r in rv if r.get("payout"))
        grid += (f'<div class="wr-rev"><i class=ico data-i=reversal></i> Reversal calls (losing side): <b class="skw">{rw}W</b> - <b class="skl">{len(rv) - rw}L</b> '
                 f'({rw / len(rv):.0%})' + (f' &middot; avg payout {sum(pays) / len(pays):.1f}x &middot; '
                 f'<span class="{"up" if ret >= 0 else "down"}">{ret:+.1f} units</span> on 1 unit each' if pays else "") + '</div>')
    daily = bucket_table(lambda t: t.date(), lambda k: k.strftime("%a %b %d"), 60, "Day by day (last 60)")
    weekly = bucket_table(lambda t: (t - dt.timedelta(days=t.weekday())).date(), lambda k: "wk of " + k.strftime("%b %d"),
                          52, "Week by week (last 52)")
    lst = []
    for r in reversed(sel[-limit:] if limit else sel):
        tm = r["t"].astimezone(et).strftime("%b %d %I:%M %p").replace(" 0", " ") if r["t"] else "?"
        call_txt = {"YES": "UP", "NO": "DOWN"}.get(r["call"], r["call"] or "-")
        act = {"YES": "UP", "NO": "DOWN"}.get(r["actual"], r["actual"] or "-")
        dec = 4 if name == "XRP" else 2
        px = (fmt_price(r["final"], dec) if r["final"] is not None else "")
        if r.get("strike"):
            px += f' vs {fmt_price(r["strike"], dec)}'
        lst.append(f'<div class="wr-row"><span>{tm}</span><span>{"<i class=ico data-i=reversal></i> " if r.get("rev") else ""}{"<i class=ico data-i=star></i> " if r.get("z80") else ""}{call_txt} &rarr; {act}{(" &middot; " + r["tier"]) if r.get("tier") else ""}'
                   f'<span class="hint"> {px}</span></span><span class="sc-chips wr-chip">{_result_chip(r["ok"], r["actual"])}</span></div>')
    more = (f'<button class="wr-btn" onclick="loadWr({{limit:{limit + 300}}})">Show more ({len(sel) - limit:,} older)</button>'
            if limit and len(sel) > limit else "")
    def btn(k, v, lab, cur_):
        return f'<button class="wr-btn{" on" if v == cur_ else ""}" onclick="loadWr({{{k}:&#39;{v}&#39;,limit:300}})">{lab}</button>'
    assets = "".join(btn("asset", a, a, name) for a in LIVE_ASSETS)
    calls = "".join(btn("call", k, v[0], call) for k, v in WR_CALLS.items())
    rngs = "".join(btn("range", k, lab, rng) for k, lab in (("today", "Today"), ("week", "This week"), ("all", "All-time")))
    return (f'<div class="wr-head"><b>ROUND HISTORY</b><button class="wr-btn" onclick="toggleWr()">Close</button></div>'
            f'<div class="wr-tabs">{assets}</div><div class="wr-tabs">{calls}</div><div class="wr-tabs">{rngs}</div>{grid}'
            f'{daily}{weekly}<div class="wr-list">{"".join(lst) or "<div class=hint>No graded rounds in this range yet.</div>"}</div>{more}'
            f'<div class="hint" style="margin-top:6px;">{allst["n"]:,} graded rounds saved for {name} (kept up to {HISTORY_CAP:,}). '
            f'<!--OWNER--><a href="/backtest" target="_blank" style="color:#e9a5bb;">Backtest report &rarr;</a><!--/OWNER--></div>')


