# ---- 2026-10-22 (user: "make the New Yorker sound older, more serious, mean but friendly - a real strong New York accent").
# No free voice has a real NYC accent. When an ElevenLabs key and a voice ID are set in Railway, Tony (and optionally Sarge)
# are spoken by that voice instead - pick a consented New York-accent voice from the ElevenLabs Voice Library:
#   ELEVENLABS_API_KEY, ELEVENLABS_TONY_VOICE_ID, (optional) ELEVENLABS_SARGE_VOICE_ID
# The real accent then does the work, so Tony's lines are NOT respelled ("goin'", "shuah") for that voice.
def _eleven_voice(key):
    if not os.environ.get("ELEVENLABS_API_KEY"):
        return None
    return os.environ.get(f"ELEVENLABS_{key.upper()}_VOICE_ID") or None


# 2026-10-22 (user: "real human voices like Speechify - Snoop, an American drill sergeant, a clear call guy"):
# set SPEECHIFY_API_KEY plus SPEECHIFY_SNOOP_VOICE_ID / SPEECHIFY_SARGE_VOICE_ID / SPEECHIFY_CALLER_VOICE_ID / (opt.)
# SPEECHIFY_AVA_VOICE_ID in Railway (voice IDs come from your Speechify account's voice list). Speechify wins, then ElevenLabs,
# then the free voice. Licensed voices only - BRAIN never clones a voice.
def _speechify_voice(key):
    if not os.environ.get("SPEECHIFY_API_KEY"):
        return None
    return os.environ.get(f"SPEECHIFY_{key.upper()}_VOICE_ID") or None


def _speechify_mp3(text, voice_id):
    import requests as _rq, base64 as _b64
    r = _rq.post("https://api.speechify.ai/v1/audio/speech",
                 headers={"Authorization": f"Bearer {os.environ['SPEECHIFY_API_KEY']}", "Content-Type": "application/json"},
                 json={"input": text, "voice_id": voice_id, "audio_format": "mp3",
                       "model": os.environ.get("SPEECHIFY_MODEL", "simba-3.5")}, timeout=15)
    r.raise_for_status()
    audio = _b64.b64decode((r.json() or {}).get("audio_data") or "")
    if len(audio) < 500:
        raise RuntimeError("empty audio")
    return audio


def _eleven_mp3(text, voice_id, key):
    import requests as _rq
    if key == "sarge":
        # 2026-10-23 (user: "a real military drill sergeant who's shouting"): Eleven v3 reads audio tags, so every line is
        # delivered as a bark. Stability 0.0 = "creative", the most expressive / loudest delivery v3 allows.
        model = os.environ.get("ELEVENLABS_SARGE_MODEL", "eleven_v3")
        body = {"text": "[shouts] " + text, "model_id": model, "voice_settings": {"stability": 0.0}}
    else:
        st = {"ava": {"stability": 0.5, "similarity_boost": 0.8, "style": 0.2, "use_speaker_boost": True}}.get(key, {})
        body = {"text": text, "model_id": os.environ.get("ELEVENLABS_MODEL", "eleven_turbo_v2_5"), "voice_settings": st}
    r = _rq.post(f"https://api.elevenlabs.io/v1/text-to-speech/{voice_id}?output_format=mp3_44100_128",
                 headers={"xi-api-key": os.environ["ELEVENLABS_API_KEY"], "Content-Type": "application/json"},
                 json=body, timeout=20)
    r.raise_for_status()
    if len(r.content) < 500:
        raise RuntimeError("empty audio")
    return r.content


def _sarge_real():
    """True when Sarge has a real (ElevenLabs or Speechify) voice set in Railway - only then is he offered on the page."""
    return bool(_eleven_voice("sarge") or _speechify_voice("sarge"))


def _persona(text, key, respell=True):
    """Rewrite a plain alert line in Tony's or Sarge's words. Same line always gets the same sign-off (so it caches)."""
    if key != "sarge":
        return text
    pick = int(hashlib.md5(text.encode()).hexdigest(), 16)
    t = text
    if key == "sarge":
        for pat, rep in _SARGE_START:
            t = re.sub(pat, rep, t)
        t = t.replace("Going up,", "Going UP!").replace("Going down,", "Going DOWN!")
        t = re.sub(r",\s+", "! ", t)                     # barked, clipped fragments
        t = re.sub(r"\.(\s|$)", r"!\1", t)              # every sentence ends hard
        t = re.sub(r"!+", "!", t).strip()
        ends = _SARGE_CAUTION if _CAUTION.search(text) else _SARGE_END
        end = ends[pick % len(ends)]
    else:
        for pat, rep in _NY_START:
            t = re.sub(pat, rep, t)
        for pat, rep in (_NY_WORDS if respell else ()):
            t = re.sub(pat, rep, t)
        pass
        ends = _NY_CAUTION if _CAUTION.search(text) else _NY_END
        end = ends[pick % len(ends)]
    # 2026-10-22 (user: "the military voice guy is overtalking with too many corny tag lines"): sign-offs only on a call
    # locking, and only about one call in three. Warnings, updates and alerts stay short and plain.
    end = ""      # 2026-10-22 (user): no sign-offs ("Hooah", "I'm tellin' ya") at all
    out = (t + " " + end).strip()
    return out if len(out) <= 220 else t[:220]


_TTS_DIR = os.path.join(_DATA_ROOT, "tts_cache")
_TTS_OK = re.compile(r"^[A-Za-z0-9 .,:;'!?%$&()\-]{1,220}$")
_tts_locks = {}
_tts_locks_guard = threading.Lock()
_tts_fail_until = [0.0]


def _tts_mp3(text, voice_key):
    text = " ".join((text or "").split())
    if not _TTS_OK.match(text):
        return None
    if voice_key not in _TTS_VOICES or (voice_key == "sarge" and not _sarge_real()):
        voice_key = "ava"
    voice = _TTS_VOICES[voice_key]
    style = _TTS_STYLE.get(voice_key, {})
    _sv = _speechify_voice(voice_key)
    if _sv:
        _ts = _persona(text, voice_key, respell=False).replace("XRP", "X R P")
        fps = os.path.join(_TTS_DIR, "sp-" + hashlib.sha1(f"{_sv}|{_ts}".encode()).hexdigest() + ".mp3")
        if os.path.isfile(fps):
            with open(fps, "rb") as f_:
                return f_.read()
        try:
            audio = _speechify_mp3(_ts, _sv)
            os.makedirs(_TTS_DIR, exist_ok=True)
            with open(fps + ".part", "wb") as f_:
                f_.write(audio)
            os.replace(fps + ".part", fps)
            return audio
        except Exception as e:
            print(f"[tts] Speechify {voice_key} failed, trying the next voice source: {e!r}")
    _ev = _eleven_voice(voice_key)
    if _ev:
        _t11 = _persona(text, voice_key, respell=False).replace("XRP", "X R P")
        fp11 = os.path.join(_TTS_DIR, "11-" + hashlib.sha1(f"{_ev}|{_t11}".encode()).hexdigest() + ".mp3")
        if os.path.isfile(fp11):
            with open(fp11, "rb") as f_:
                return f_.read()
        try:
            audio = _eleven_mp3(_t11, _ev, voice_key)
            os.makedirs(_TTS_DIR, exist_ok=True)
            with open(fp11 + ".part", "wb") as f_:
                f_.write(audio)
            os.replace(fp11 + ".part", fp11)
            return audio
        except Exception as e:
            print(f"[tts] ElevenLabs {voice_key} failed, using the free voice: {e!r}")
    text = _persona(text, voice_key)
    rate, pitch, volume = style.get("rate", "+4%"), style.get("pitch", "+0Hz"), style.get("volume", "+0%")
    key = hashlib.sha1(f"{voice}|{rate}|{pitch}|{volume}|{text}".encode()).hexdigest()
    fp = os.path.join(_TTS_DIR, key + ".mp3")
    if os.path.isfile(fp):
        with open(fp, "rb") as f_:
            return f_.read()
    if time.time() < _tts_fail_until[0]:
        return None
    with _tts_locks_guard:
        lk = _tts_locks.setdefault(key, threading.Lock())
    with lk:
        if os.path.isfile(fp):
            with open(fp, "rb") as f_:
                return f_.read()
        try:
            import asyncio
            import edge_tts
            os.makedirs(_TTS_DIR, exist_ok=True)
            tmp = fp + ".part"

            async def _gen():
                await edge_tts.Communicate(text.replace("XRP", "X R P"), voice, rate=rate, pitch=pitch, volume=volume).save(tmp)
            asyncio.run(asyncio.wait_for(_gen(), timeout=12))
            if os.path.getsize(tmp) < 500:
                raise RuntimeError("empty audio")
            os.replace(tmp, fp)
            _tts_trim_cache()
            with open(fp, "rb") as f_:
                return f_.read()
        except Exception as e:
            print(f"[tts] {voice} failed: {e!r}")
            _tts_fail_until[0] = time.time() + 60          # back off for a minute; the page uses the device voice meanwhile
            return None
        finally:
            with _tts_locks_guard:
                _tts_locks.pop(key, None)


def _tts_trim_cache(keep=3000):
    try:
        files = [os.path.join(_TTS_DIR, f) for f in os.listdir(_TTS_DIR) if f.endswith(".mp3")]
        if len(files) > keep:
            files.sort(key=os.path.getmtime)
            for f in files[:len(files) - keep]:
                os.remove(f)
    except Exception:
        pass


