TARGET_MATCH_PCT = 0.05       # "the same price target" = exact, or within 5%


MINI_CALL_ON = False           # 2026-10-23 (user): "get rid of the mini call" - not made, not shown
MINI_CALL_N = 10               # 2026-10-22 (user): mini call from the last 10 rounds near the target
TARGET_RECENT_PCT = 0.01       # 2026-10-22 (user): exact target first, then the closest within 1%, from the last 30 days
TARGET_LOOKBACK_S = 30 * 86400
_tgt_cache = {}
_TGT_BODY = {}            # inner html of the target history (shown inside BEEN HERE BEFORE)
_TGT_MINI_CALL = {}       # latest mini call per coin {ticker, call, pct, n} - locked into the round at 8:00
_TGT_MINI = {}            # latest mini call html per coin (also shown in the price-vs-line panel)


def _target_touches(name, line):
    """When did price last trade AT this target (a candle whose low-high range contains it), or come closest, using the
    live 1-minute candles first, then hourly, then daily for older history. Returns [(ts, tf, exact, price, move_after)]."""
    sym = {a["name"]: a["symbol"] for a in DASHBOARD_ASSETS}.get(name)
    if name == "BTC":                                    # 30 days of real 1-minute candles from the backtest pull
        try:
            m1 = _bt.minute_candles()
            if m1:
                ks = sorted(m1)
                for t in reversed(ks[:-1]):
                    o, h, l, c, _v = m1[t]
                    if l <= line <= h:
                        later = m1.get(t + 900)
                        return [(t, "1m", True, line, ((later[3] - line) / line) if later else None)]
                t = min(ks, key=lambda k: min(abs(m1[k][1] - line), abs(m1[k][2] - line)))
                near = m1[t][1] if abs(m1[t][1] - line) < abs(m1[t][2] - line) else m1[t][2]
                return [(t, "1m", False, near, None)]
        except Exception as _me:
            print(f"[target history] minute data: {_me!r}")
    if _mtf is None or not sym:
        return []
    out, seen_tf = [], set()
    for tf in ("1m", "1h", "1d"):
        cs = (_mtf.windows.get(sym) or {}).get(tf) or []
        if len(cs) < 3:
            continue
        hit = None
        for i in range(len(cs) - 2, -1, -1):              # newest closed candle first
            c = cs[i]
            if c[3] <= line <= c[2]:
                after = cs[min(len(cs) - 1, i + {"1m": 15, "1h": 1, "1d": 1}[tf])][4]
                hit = (c[0], tf, True, line, (after - line) / line)
                break
        if hit is None:                                   # never touched in this window: the closest candle instead
            i = min(range(len(cs) - 1), key=lambda k: min(abs(cs[k][2] - line), abs(cs[k][3] - line)))
            c = cs[i]
            near = c[2] if abs(c[2] - line) < abs(c[3] - line) else c[3]
            hit = (c[0], tf, False, near, None)
        out.append(hit)
        seen_tf.add(tf)
        if hit[2]:
            break                                         # exact touch found - no need to look further back
    return out


def _mini_from_pool(line, pool):
    """Instant mini call from a pool of settled rounds [(close_ts, strike, up_bool)], newest-first logic as on screen."""
    near = sorted((x for x in pool if x[1] and abs(x[1] - line) / line <= TARGET_RECENT_PCT), key=lambda x: -x[0])[:MINI_CALL_N]
    if len(near) < MINI_CALL_N:
        used = {id(x) for x in near}
        near += sorted((x for x in pool if x[1] and id(x) not in used), key=lambda x: (abs(x[1] - line), -x[0]))[:MINI_CALL_N - len(near)]
        near.sort(key=lambda x: -x[0])
    if len(near) < MINI_CALL_N:
        return None
    ups = sum(1 for x in near if x[2])
    if ups * 2 == len(near):
        u5 = sum(1 for x in near[:5] if x[2])
        up = u5 * 2 > 5
        pct = max(u5, 5 - u5) / 5
    else:
        up = ups * 2 > len(near)
        pct = max(ups, len(near) - ups) / len(near)
    return {"call": "YES" if up else "NO", "pct": round(pct, 3)}


def backfill_mini_calls():
    """2026-10-22 (user: "backtest the mini call on the actual rounds since everything else started tracking"): for every graded
    round in the history that has no mini call yet, work out the INSTANT mini call it would have made - using only rounds that
    had already settled before that round opened - and grade it against the real result. Marked mini_bf so it's honest."""
    changed = 0
    for name, hist in list(_history.items()):
        pool = []
        if name == "BTC":
            try:
                pool = [(m["close"], m["strike"], m["result"] == "yes") for m in _bt.settled_markets()
                        if m.get("strike") and m.get("result") in ("yes", "no")]
            except Exception:
                pool = []
        seen = {round(x[0]) for x in pool}
        hpool = []
        for h in hist:
            t = _window_close_utc(h.get("ticker"))
            if t and h.get("strike") and h.get("actual_side") in ("YES", "NO") and round(t.timestamp()) not in seen:
                hpool.append((t.timestamp(), h["strike"], h["actual_side"] == "YES"))
        allp = sorted(pool + hpool, key=lambda x: x[0])
        for h in hist:
            if h.get("mini_call") or h.get("actual_side") not in ("YES", "NO") or not h.get("strike"):
                continue
            t = _window_close_utc(h.get("ticker"))
            if not t:
                continue
            opn = t.timestamp() - 900
            prior = [x for x in allp if x[0] <= opn and opn - x[0] <= TARGET_LOOKBACK_S]
            mc = _mini_from_pool(h["strike"], prior)
            if not mc:
                continue
            h["mini_call"], h["mini_pct"], h["mini_bf"] = mc["call"], mc["pct"], True
            h["mini_correct"] = mc["call"] == h["actual_side"]
            changed += 1
    if changed:
        _save_history()
        print(f"[mini call] backfilled {changed} tracked rounds")
    for name, hist in list(_history.items()):
        for k_ in ("mini", "sealed", "early"):
            g = [h for h in hist if h.get(f"{k_}_correct") is not None and not h.get(f"{k_}_reversal")]
            if g:
                w = sum(1 for h in g if h[f"{k_}_correct"])
                print(f"[mini call] RECORD {name} {k_}: {w}/{len(g)} right ({w / len(g):.1%})")
    return changed


# ---------------------------------------------------------------- MINI CALL FORMULA SEARCH (2026-10-22, user)
# "Analyze the mini call to find the real best way to read it - is there a higher % with a better formula, 10 rounds vs 5?"
# Every variant makes the INSTANT call at the round's open from rounds that had already settled. Chosen on the older 70% of
# rounds, graded on the newest 30% it never saw. Results go to the log and to mini_grid.json.
MINI_GRID_FILE = os.path.join(_DATA_ROOT, "data_cache", "mini_grid.json")


def mini_grid_search():
    out = {"ts": time.time(), "assets": {}}
    for name in ("BTC", "XRP"):
        rows = []
        if name == "BTC":
            try:
                rows = [(m["close"], m["strike"], m["result"] == "yes") for m in _bt.settled_markets()
                        if m.get("strike") and m.get("result") in ("yes", "no")]
            except Exception:
                rows = []
        seen = {round(r[0]) for r in rows}
        for h in _history.get(name, []):
            t = _window_close_utc(h.get("ticker"))
            if t and h.get("strike") and h.get("actual_side") in ("YES", "NO") and round(t.timestamp()) not in seen:
                rows.append((t.timestamp(), h["strike"], h["actual_side"] == "YES"))
        rows.sort(key=lambda r: r[0])
        if len(rows) < 120:
            continue
        RADII = (0.001, 0.0025, 0.005, 0.01, 0.02)
        NS = (3, 5, 7, 10, 15, 20)
        # per round: newest-first near lists per radius (up to 20), plus context features
        feats = []
        for i, (ts, line, up) in enumerate(rows):
            if i < 30:
                continue
            opn = ts - 900
            near = {r: [] for r in RADII}
            j = i - 1
            while j >= 0 and opn - rows[j][0] <= TARGET_LOOKBACK_S and min(len(v) for v in near.values()) < 20:
                pj = rows[j]
                if pj[0] <= opn:
                    d = abs(pj[1] - line) / line
                    for r in RADII:
                        if d <= r and len(near[r]) < 20:
                            near[r].append((pj[2], d, opn - pj[0]))
                j -= 1
            last = [rows[k][2] for k in range(i - 1, max(-1, i - 21), -1)]          # newest-first, any target
            drift = line - rows[i - 4][1] if i >= 4 else 0.0                       # strike change over the last hour
            feats.append({"up": up, "near": near, "last": last, "drift": drift, "prev": rows[i - 1][2]})
            if i % 300 == 0:
                time.sleep(0.01)
        split = int(len(feats) * 0.7)

        def score(fn):
            res = []
            for f in feats:
                c = fn(f)
                res.append(None if c is None else (c == f["up"]))
            def summ(xs):
                g = [x for x in xs if x is not None]
                return {"n": len(g), "win": (sum(g) / len(g)) if g else None, "cov": len(g) / max(1, len(xs))}
            return summ(res[:split]), summ(res[split:]), summ(res)

        def maj(votes, w=None, thr=0.5, tie5=False):
            if not votes:
                return None
            w = w or [1.0] * len(votes)
            tot = sum(w)
            upw = sum(wi for v, wi in zip(votes, w) if v)
            sh = upw / tot
            if abs(sh - 0.5) < 1e-9:
                if tie5:
                    v5 = votes[:5]
                    u5 = sum(v5)
                    return None if u5 * 2 == len(v5) else (u5 * 2 > len(v5))
                return None
            if max(sh, 1 - sh) < thr:
                return None
            return sh > 0.5

        variants = []
        for r in RADII:
            for n in NS:
                for wmode in ("plain", "recent", "close"):
                    for thr in (0.5, 0.6, 0.7, 0.8):
                        def fn(f, r=r, n=n, wmode=wmode, thr=thr):
                            nr = f["near"][r][:n]
                            if len(nr) < n:
                                return None
                            votes = [x[0] for x in nr]
                            w = None
                            if wmode == "recent":
                                w = [0.85 ** k for k in range(len(nr))]
                            elif wmode == "close":
                                w = [1.0 / (1.0 + x[1] / 0.001) for x in nr]
                            return maj(votes, w, thr, tie5=(thr == 0.5))
                        variants.append((f"near{r * 100:g}% last{n} {wmode} {'all' if thr == 0.5 else f'only {thr:.0%}+ agree'}", fn))
        variants.append(("CURRENT: near1% last10, tie -> newest 5", lambda f: maj([x[0] for x in f["near"][0.01][:10]], None, 0.5, True)
                         if len(f["near"][0.01]) >= 10 else None))
        for n in (3, 5, 10, 20):
            variants.append((f"last{n} rounds any target (momentum)", lambda f, n=n: maj(f["last"][:n], None, 0.5, False)))
            variants.append((f"fade last{n} rounds any target", lambda f, n=n: (lambda m: None if m is None else (not m))(maj(f["last"][:n], None, 0.5, False))))
        variants.append(("previous round repeats", lambda f: f["prev"]))
        variants.append(("previous round flips", lambda f: not f["prev"]))
        variants.append(("1h drift (strike rising -> UP)", lambda f: None if f["drift"] == 0 else f["drift"] > 0))
        variants.append(("1h drift fade", lambda f: None if f["drift"] == 0 else f["drift"] < 0))
        for r in (0.005, 0.01):
            for n in (5, 10):
                variants.append((f"near{r * 100:g}% last{n} + 1h drift must agree",
                                 lambda f, r=r, n=n: (lambda m: None if (m is None or f["drift"] == 0 or (f["drift"] > 0) != m) else m)(
                                     maj([x[0] for x in f["near"][r][:n]], None, 0.5, True) if len(f["near"][r]) >= n else None)))
        results = []
        for k_, (lab, fn) in enumerate(variants):
            tr, ho, al = score(fn)
            results.append({"name": lab, "train": tr, "hold": ho, "all": al})
            if k_ % 50 == 0:
                time.sleep(0.01)
        base = next(x for x in results if x["name"].startswith("CURRENT"))
        # pick on TRAIN only: best win rate with >= 60% coverage, and best with >= 25% coverage
        def pick(mincov):
            ok = [x for x in results if x["train"]["win"] is not None and x["train"]["cov"] >= mincov and x["train"]["n"] >= 80]
            return max(ok, key=lambda x: x["train"]["win"]) if ok else None
        picks = {"every_round": pick(0.95), "most_rounds": pick(0.6), "selective": pick(0.25)}
        out["assets"][name] = {"rounds": len(feats), "current": base, "picks": picks,
                               "top_hold": sorted((x for x in results if x["hold"]["n"] >= 40 and x["train"]["n"] >= 80),
                                                  key=lambda x: -(x["hold"]["win"] or 0))[:8]}
        f_ = lambda x: (f'{x["hold"]["win"] * 100:.1f}% of {x["hold"]["n"]} unseen ({x["hold"]["cov"] * 100:.0f}% of rounds called) '
                        f'| train {x["train"]["win"] * 100:.1f}% of {x["train"]["n"]}') if x and x["hold"]["win"] is not None else "-"
        print(f"[mini grid] {name}: {len(feats)} rounds, newest {len(feats) - split} unseen")
        print(f"[mini grid] {name} CURRENT method: {f_(base)}")
        for k_, v in picks.items():
            print(f"[mini grid] {name} BEST ({k_}) = {v['name'] if v else '-'}: {f_(v)}")
        for x in out["assets"][name]["top_hold"][:5]:
            print(f"[mini grid] {name} top unseen: {x['name']}: {f_(x)}")
    try:
        os.makedirs(os.path.dirname(MINI_GRID_FILE), exist_ok=True)
        with open(MINI_GRID_FILE, "w") as fh:
            json.dump(out, fh)
    except Exception:
        pass
    return out


_mini_grid_ts = [0.0]
_mini2_ts = [0.0]


def _mini_backfill_loop():
    time.sleep(60)
    while True:
        try:
            if time.time() - _mini2_ts[0] > 6 * 3600:
                _mini2_ts[0] = time.time()
                mini2_backtest()
                mini2_pattern_test()
        except Exception as _e:
            print(f"[mini2] backtest: {_e!r}")
        try:
            if time.time() - _mini_grid_ts[0] > 6 * 3600:
                _mini_grid_ts[0] = time.time()
                mini_grid_search()
        except Exception as _e:
            print(f"[mini grid] {_e!r}")
        time.sleep(1800)


_hc_idx = {"ts": 0, "rows": None}


def _history_check_index():
    """[(minute 0-14, distance from the line, ended_up)] for every BTC round of the last 30 days, from 1-minute closes."""
    if _hc_idx["rows"] is not None and time.time() - _hc_idx["ts"] < 900:
        return _hc_idx["rows"]
    rows = []
    try:
        m1 = _bt.minute_candles()
        for m in _bt.settled_markets():
            if not m.get("strike") or m.get("result") not in ("yes", "no"):
                continue
            o = int(m.get("open") or (m["close"] - 900)) // 60 * 60
            up = m["result"] == "yes"
            for k in range(15):
                c = m1.get(o + k * 60)
                if c:
                    rows.append((k, (c[3] - m["strike"]) / m["strike"], up))
    except Exception as _e:
        print(f"[history check] {_e!r}")
    _hc_idx.update(ts=time.time(), rows=rows)
    return rows


def history_check(name, spot, line, elapsed):
    """2026-10-22: the in-round read - of all rounds in the last 30 days where price was this far from the line at this same
    minute, how many ended UP. {"call", "pct", "n", "minute", "dist"} or None (BTC only - needs the 1-minute history)."""
    if name != "BTC" or not spot or not line:
        return None
    rows = _history_check_index()
    if not rows:
        return None
    k = max(0, min(14, int((elapsed or 0) // 60)))
    d = (spot - line) / line
    band = max(0.0002, abs(d) * 0.25)
    sel = [r for r in rows if r[0] == k and abs(r[1] - d) <= band]
    if len(sel) < 30:
        sel = [r for r in rows if abs(r[0] - k) <= 1 and abs(r[1] - d) <= band * 1.5]
    if len(sel) < 30:
        return None
    ups = sum(1 for r in sel if r[2])
    up = ups * 2 >= len(sel)
    return {"call": "YES" if up else "NO", "pct": max(ups, len(sel) - ups) / len(sel), "n": len(sel), "minute": k, "dist": d}


# ---------------------------------------------------------------- MINI CALL v2 (2026-10-22 20:12, user)
# "Rework the mini call: restart its win rate, and base it on the last 2 minutes of the previous round + the first minute of
# this one, factored with whether RSI, MACD and the other background indicators read bullish or bearish." Called at 1:00.
# The SAME vote formula is backtested on 30 days of BTC 1-minute data (picked on older rounds, graded on newest unseen) so
# you can see whether it beats simpler ways of calling.
MINI2_FILE = os.path.join(_DATA_ROOT, "data_cache", "mini2.json")
MINI2_KEYS = ("move3", "line", "rsi", "macd", "macd_slope", "ema")
MINI2_LABEL = {"pressure": "buy pressure", "mtrend": "market trend", "move3": "last 3 min of price", "line": "price vs the line", "rsi": "RSI", "macd": "MACD",
               "macd_slope": "MACD turning", "ema": "EMA trend", "patterns": "chart patterns"}
MINI2_SINCE = 1792714500          # 2026-10-23 00:15 UTC (8:15 PM ET Oct 22) - the v2 record starts here


def _ema_list(vals, n):
    k, out, e = 2 / (n + 1), [], None
    for v in vals:
        e = v if e is None else v * k + e * (1 - k)
        out.append(e)
    return out


def _rsi14(cl):
    if len(cl) < 15:
        return None
    g = l_ = 0.0
    for i in range(1, 15):
        d = cl[i] - cl[i - 1]
        g += max(d, 0); l_ += max(-d, 0)
    ag, al = g / 14, l_ / 14
    for i in range(15, len(cl)):
        d = cl[i] - cl[i - 1]
        ag = (ag * 13 + max(d, 0)) / 14; al = (al * 13 + max(-d, 0)) / 14
    return 100.0 if al == 0 else 100 - 100 / (1 + ag / al)


def mini2_votes(cl, line):
    """+1 / -1 / 0 per read, from 1-minute closes ending at ~1:00 into the round (the last one = price at 1:00)."""
    if not cl or len(cl) < 30 or not line:
        return None
    px = cl[-1]
    e12, e26 = _ema_list(cl, 12), _ema_list(cl, 26)
    macd = [a - b for a, b in zip(e12, e26)]
    sig = _ema_list(macd, 9)
    hist = [a - b for a, b in zip(macd, sig)]
    tiny = px * 0.00002
    r = _rsi14(cl[-60:])
    e50 = _ema_list(cl, 50)
    sgn = lambda x, t=0.0: 1 if x > t else (-1 if x < -t else 0)
    return {"move3": sgn(px - cl[-4], tiny), "line": sgn(px - line, tiny),
            "rsi": 0 if r is None else (1 if r >= 55 else (-1 if r <= 45 else 0)),
            "macd": sgn(hist[-1], tiny), "macd_slope": sgn(hist[-1] - hist[-2], tiny / 4),
            "ema": sgn(e12[-1] - e50[-1], tiny), "_rsi": r, "_hist": hist[-1]}


def mini2_combine(v, keys):
    tot = sum(v[k] for k in keys)
    if tot == 0:
        tot = v["line"] or v["move3"] or 1          # tie: price vs the line, then the 3-minute move
    agree = sum(1 for k in keys if v[k] == (1 if tot > 0 else -1))
    return ("YES" if tot > 0 else "NO"), agree, len(keys)


def mini2_config():
    try:
        with open(MINI2_FILE) as fh:
            c = json.load(fh)
        if c.get("keys"):
            return c
    except Exception:
        pass
    return {"keys": list(MINI2_KEYS)}


def mini2_backtest():
    """Every 30-day BTC round: votes at 1:00 from 1-minute closes, every combination of reads, picked on the older 70%,
    graded on the newest 30%. Saves the pick (used live) + baselines, logs the comparison."""
    import itertools
    m1 = _bt.minute_candles()
    mk = sorted((m for m in _bt.settled_markets() if m.get("strike") and m.get("result") in ("yes", "no")), key=lambda m: m["close"])
    rows = []
    for i, m in enumerate(mk):
        o = int(m.get("open") or (m["close"] - 900)) // 60 * 60
        cl = [m1[t][3] for t in range(o - 3600, o + 60, 60) if t in m1]
        if len(cl) < 50 or (o not in m1):
            continue
        v = mini2_votes(cl, m["strike"])
        if v:
            rows.append((v, m["result"] == "yes"))
        if i % 300 == 0:
            time.sleep(0.01)
    if len(rows) < 300:
        return None
    split = int(len(rows) * 0.7)

    def ev(keys, part):
        g = [(mini2_combine(v, keys)[0] == "YES") == up for v, up in part]
        return sum(g) / len(g)
    combos = [list(c) for r in (3, 5) for c in itertools.combinations(MINI2_KEYS, r)]     # odd, 3+ reads: no ties
    scored = [(ev(c, rows[:split]), c) for c in combos]
    scored.sort(key=lambda x: -x[0])
    best = scored[0][1]
    res = {"ts": time.time(), "rounds": len(rows), "unseen": len(rows) - split, "keys": best,
           "train": scored[0][0], "hold": ev(best, rows[split:]),
           "all_reads": {"train": ev(list(MINI2_KEYS), rows[:split]), "hold": ev(list(MINI2_KEYS), rows[split:])},
           "line_only": {"hold": ev(["line"], rows[split:])}, "move3_only": {"hold": ev(["move3"], rows[split:])},
           "top": [{"keys": c, "train": t, "hold": ev(c, rows[split:])} for t, c in scored[:6]]}
    try:
        os.makedirs(os.path.dirname(MINI2_FILE), exist_ok=True)
        with open(MINI2_FILE, "w") as fh:
            json.dump(res, fh)
    except Exception:
        pass
    print(f"[mini2] 30-day BTC test at 1:00: {res['rounds']} rounds, newest {res['unseen']} unseen")
    print(f"[mini2] PICK {'+'.join(best)}: unseen {res['hold']:.1%} (train {res['train']:.1%})")
    print(f"[mini2] all reads equal: unseen {res['all_reads']['hold']:.1%} | price vs line alone: {res['line_only']['hold']:.1%} "
          f"| last-3-min move alone: {res['move3_only']['hold']:.1%}")
    for x in res["top"]:
        print(f"[mini2]   {'+'.join(x['keys'])}: train {x['train']:.1%} unseen {x['hold']:.1%}")
    return res


def mini2_pattern_test():
    """2026-10-22 (user: "base it off the chart-pattern data BRAIN has actually recorded"): replay every round since the
    pattern log began. At 1:00 each round gets the pattern vote from the proven bullish / bearish patterns BRAIN logged as
    COMPLETED on the 1m / 5m charts in the 15 minutes before that moment (same rule as live). Compares, on exactly those
    rounds: price+indicator reads alone, the same + the pattern vote, the pattern vote alone, and price vs the line."""
    import csv as _csv
    try:
        from mtf_structure import EVENTS_FILE as _EV
    except Exception:
        return None
    evs = {}
    try:
        with open(_EV, encoding="utf-8") as f:
            for r in _csv.DictReader(f):
                if r.get("event") != "complete" or r.get("tf") not in ("1m", "5m") or r.get("bias") not in ("bullish", "bearish"):
                    continue
                try:
                    ts = dt.datetime.fromisoformat(r["ts_utc"]).timestamp()
                except Exception:
                    continue
                evs.setdefault(r["asset"], []).append((ts, r["tf"], r["name"], r["bias"]))
    except OSError:
        return None
    rate_cache = {}

    def rate(asset, tf, nm):
        k = (asset, tf, nm)
        if k not in rate_cache:
            try:
                st = _mtf.stats.summary(asset, tf, nm) if _mtf is not None else {}
            except Exception:
                st = {}
            ok = (st.get("decisive") or 0) >= CHART_PAT_MIN_N and (st.get("rate") or 0) >= 0.5
            rate_cache[k] = (st.get("rate") or 0.5) if ok else None
        return rate_cache[k]

    def pat_vote(asset, t):
        sc = 0.0
        for ts, tf, nm, b in evs.get(asset, []):
            if t - 900 <= ts <= t:
                r_ = rate(asset, tf, nm)
                if r_ is not None:
                    w = max(0.0, r_ - 0.5)
                    sc += w if b == "bullish" else -w
        return 1 if sc > 0.02 else (-1 if sc < -0.02 else 0)

    out = {}
    cfg = mini2_config()
    keys = [k for k in cfg.get("keys") or MINI2_KEYS if k in MINI2_KEYS] or list(MINI2_KEYS)
    m1 = _bt.minute_candles()
    first = min((e[0] for e in evs.get("BTC", [])), default=None)
    if first:
        rows = []
        for m in _bt.settled_markets():
            if not m.get("strike") or m.get("result") not in ("yes", "no"):
                continue
            o = int(m.get("open") or (m["close"] - 900)) // 60 * 60
            if o + 60 < first + 900:
                continue
            cl = [m1[t][3] for t in range(o - 3600, o + 60, 60) if t in m1]
            v = mini2_votes(cl, m["strike"]) if len(cl) >= 50 else None
            if not v:
                continue
            v["patterns"] = pat_vote("BTC", o + 60)
            rows.append((v, m["result"] == "yes"))
        if rows:
            def acc(fn):
                g = [(c == "YES") == up for v, up in rows for c in [fn(v)] if c]
                return (sum(g) / len(g) if g else None, len(g))
            base = acc(lambda v: mini2_combine(v, keys)[0])
            withp = acc(lambda v: mini2_combine(v, keys + (["patterns"] if v["patterns"] else []))[0])
            ponly = acc(lambda v: ("YES" if v["patterns"] > 0 else "NO") if v["patterns"] else None)
            line = acc(lambda v: mini2_combine(v, ["line"])[0])
            n_p = sum(1 for v, _ in rows if v["patterns"])
            out["BTC"] = {"rounds": len(rows), "since": first, "with_patterns_n": n_p, "reads": base, "reads_plus_patterns": withp,
                          "patterns_only": ponly, "line_only": line}
            print(f"[mini2 patterns] BTC: {len(rows)} rounds since the pattern log began "
                  f"({dt.datetime.fromtimestamp(first, ZoneInfo('America/New_York')):%b %d %-I:%M %p}); a proven pattern was in play in {n_p}")
            f_ = lambda x: "-" if x[0] is None else f"{x[0]:.1%} of {x[1]}"
            print(f"[mini2 patterns] BTC reads only: {f_(base)} | reads + patterns: {f_(withp)} | patterns alone: {f_(ponly)} | price vs line: {f_(line)}")
    try:
        c = mini2_config()
        c["patterns_test"] = out
        with open(MINI2_FILE, "w") as fh:
            json.dump(c, fh)
    except Exception:
        pass
    return out


def mini2_live(sym, live_price, line, flow_pct=None, trend=None):
    """Live votes at ~1:00 from the 1-minute history (+ the live price as the latest close)."""
    try:
        cs = (_mtf.windows.get(sym) or {}).get("1m") or []
        cl = [c[4] for c in cs[-80:]]
    except Exception:
        cl = []
    if live_price:
        cl = cl + [live_price]
    v = mini2_votes(cl, line)
    if not v:
        return None
    cfg = mini2_config()
    keys = [k for k in cfg.get("keys") or MINI2_KEYS if k in MINI2_KEYS] or list(MINI2_KEYS)
    if len(keys) < 3 or len(keys) % 2 == 0:
        keys = ["move3", "line", "rsi", "macd", "ema"]
    # 2026-10-22 (user): also read BRAIN's chart patterns - only the proven ones (80%+ formed, right on this coin + timeframe)
    # from the last 15 minutes on the 1m / 5m charts, weighted by how often each has worked
    try:
        name = next((a_["name"] for a_ in DASHBOARD_ASSETS if a_["symbol"] == sym), None)
        ps, pn = 0.0, []
        for tf in ("1m", "5m"):
            for it in (chart_patterns_payload(name, tf).get("items") or []) if name else []:
                if time.time() - (it.get("ts") or 0) > 900 or it.get("bias") not in ("bullish", "bearish"):
                    continue
                w = max(0.0, (it.get("rate") or 0.5) - 0.5)
                ps += w if it["bias"] == "bullish" else -w
                pn.append(f'{it["name"]} {tf}')
        v["patterns"] = 1 if ps > 0.02 else (-1 if ps < -0.02 else 0)
        # 2026-10-22: tested on every round since BRAIN started logging patterns - adding them DROPPED the hit rate
        # (59% -> 55%, patterns alone 51%), so they are shown for reference but do NOT vote
        v["_pat"] = pn[:3]
    except Exception as _pe:
        print(f"[mini2] patterns: {_pe!r}")
    # 2026-10-22 (user): heavily weigh buy pressure across the end of the last round + this round, mixed with market trend
    if flow_pct is not None:
        v["pressure"] = 1 if flow_pct >= 0.55 else (-1 if flow_pct <= 0.45 else 0)
        keys = keys + ["pressure", "pressure"]
    if trend:
        v["mtrend"] = 1 if trend > 0 else -1
        keys = keys + ["mtrend"]
    call, agree, of = mini2_combine(v, keys)
    reasons = [f'{MINI2_LABEL[k]} {"up" if v[k] > 0 else ("down" if v[k] < 0 else "flat")}' for k in keys]
    reasons = []                    # 2026-10-22 (user): don't explain how the mini call works on screen
    return {"call": call, "agree": agree, "of": of, "keys": keys, "reasons": reasons,
            "rsi": round(v["_rsi"], 1) if v["_rsi"] is not None else None}


def mini_call_now(name, line, spot, elapsed, ticker, dec):
    """The mini call for this round right now (computes the BEEN HERE BEFORE panel if needed)."""
    if not line:
        return None
    target_history_html(name, {"target_price": line, "spot_price": spot, "elapsed_seconds": elapsed, "ticker": ticker,
                               "price_decimals": dec})
    mc = _TGT_MINI_CALL.get(name)
    return mc if mc and mc.get("ticker") == ticker else None


_mini_bt = {"ts": 0, "res": None, "busy": False}


def mini_backtest():
    """How the mini-call method would have done on the last 30 days of BTC rounds - each round only sees rounds that
    had already settled before it opened (no peeking). Cached 6h, computed in the background."""
    if _mini_bt["busy"] or (time.time() - _mini_bt["ts"] < 6 * 3600 and _mini_bt["res"] is not None):
        return _mini_bt["res"]

    def _run():
        try:
            mk = sorted((m for m in _bt.settled_markets() if m.get("strike") and m.get("result") in ("yes", "no")),
                        key=lambda m: m["close"])
            wins = n = 0
            for i, m in enumerate(mk):
                line = m["strike"]
                opn = m.get("open") or (m["close"] - 900)
                prev = [x for x in mk[:i] if x["close"] <= opn and opn - x["close"] <= TARGET_LOOKBACK_S]
                if len(prev) < MINI_CALL_N:
                    continue
                near = sorted((x for x in prev if abs(x["strike"] - line) / line <= TARGET_RECENT_PCT), key=lambda x: -x["close"])[:MINI_CALL_N]
                if len(near) < MINI_CALL_N:
                    used = {id(x) for x in near}
                    near += sorted((x for x in prev if id(x) not in used), key=lambda x: (abs(x["strike"] - line), -x["close"]))[:MINI_CALL_N - len(near)]
                    near.sort(key=lambda x: -x["close"])
                ups = sum(1 for x in near if x["result"] == "yes")
                if ups * 2 == len(near):
                    u5 = sum(1 for x in near[:5] if x["result"] == "yes")
                    up = u5 * 2 > len(near[:5])
                else:
                    up = ups * 2 > len(near)
                n += 1
                wins += int(up == (m["result"] == "yes"))
                if i % 200 == 0:
                    time.sleep(0.01)
            _mini_bt["res"] = {"n": n, "wins": wins}
        except Exception as _e:
            print(f"[mini backtest] {_e!r}")
        finally:
            _mini_bt["ts"], _mini_bt["busy"] = time.time(), False

    _mini_bt["busy"] = True
    threading.Thread(target=_run, daemon=True, name="mini-backtest").start()
    return _mini_bt["res"]


def target_history_html(name, d):
    """2026-10-22 (user): rounds from the most recent day whose target was within 1% (closest first), filled with the next
    closest if there aren't enough; then the last time price actually traded AT this target on the chart (or closest)."""
    line = d.get("target_price")
    if not line:
        return ""
    _sp = d.get("spot_price")
    _side_now = None if _sp is None else (_sp >= line)
    _el_min = int((d.get("elapsed_seconds") or 0) // 60)
    ck = (name, round(line, 6), _side_now, _el_min)
    hit = _tgt_cache.get(ck)
    if hit and time.time() - hit[0] < 30:
        if len(hit) > 2:
            _TGT_BODY[name] = hit[2]
        return hit[1]
    dec = d.get("price_decimals", 2)
    cur = d.get("ticker", "")
    et = ZoneInfo("America/New_York")
    now = time.time()
    rounds = {}
    for h in _history.get(name, []):
        st, act = h.get("strike"), h.get("actual_side")
        if st and act in ("YES", "NO") and h.get("ticker") != cur:
            t = _window_close_utc(h.get("ticker"))
            rounds[h["ticker"]] = {"strike": st, "up": act == "YES", "ts": t.timestamp() if t else 0, "h": h}
    if name == "BTC":
        try:
            for m in _bt.settled_markets():
                if m.get("strike") and m["ticker"] not in rounds and m["ticker"] != cur:
                    rounds[m["ticker"]] = {"strike": m["strike"], "up": m["result"] == "yes", "ts": m["close"], "open": m.get("open"), "h": None}
        except Exception:
            pass
    rs = list(rounds.values())
    for r in rs:
        r["diff"] = abs(r["strike"] - line) / line
    # 2026-10-22 (b, user): the EXACT target if it happened in the last 30 days, otherwise the closest within 1% (the most
    # recent breaks a tie), otherwise simply the nearest target on record
    rs = [r for r in rs if now - r["ts"] <= TARGET_LOOKBACK_S]
    # 2026-10-22 (c, user): the 10 MOST RECENT rounds (last 30 days) whose target was within 1% -> a "mini call" from
    # the majority. If fewer than 10 are that close, the next-closest targets fill in.
    near = sorted((r for r in rs if r["diff"] <= TARGET_RECENT_PCT), key=lambda r: -r["ts"])[:MINI_CALL_N]
    if len(near) < MINI_CALL_N:
        used = {id(r) for r in near}
        near += sorted((r for r in rs if id(r) not in used), key=lambda r: (r["diff"], -r["ts"]))[:MINI_CALL_N - len(near)]
        near.sort(key=lambda r: -r["ts"])
    recent = near
    mini = ""
    if near:
        ups = sum(1 for r in near if r["up"])
        dn = len(near) - ups
        if ups != dn:
            side_up = ups > dn
            pct = max(ups, dn) / len(near)
            sub = f"{max(ups, dn)} of {len(near)} recent rounds near this target ended {'UP' if side_up else 'DOWN'}"
        else:
            # 2026-10-22 (user): a split goes to whichever side won more of the newest 5
            last5 = near[:5]
            u5 = sum(1 for r in last5 if r["up"])
            side_up = u5 > len(last5) - u5
            pct = max(u5, len(last5) - u5) / len(last5)
            sub = (f"{ups}-{dn} split over {len(near)} - tie broken by the newest {len(last5)}: "
                   f"{max(u5, len(last5) - u5)} of {len(last5)} ended {'UP' if side_up else 'DOWN'}")
        cls = "up" if side_up else "down"
        word = "UP" if side_up else "DOWN"
        _TGT_MINI_CALL[name] = {"ticker": cur, "call": "YES" if side_up else "NO", "pct": round(pct, 3), "n": len(near)}
        mini = (f'<div class="mini-call mc-{cls}"><span class="mc-lbl">MINI CALL</span><b class="mc-dir">{word}</b>'
                f'<span class="mc-pct">{pct * 100:.0f}%</span><span class="mc-sub">{sub}</span></div>')
        # same spot: of those near rounds, the ones where price was on the SAME side of the line at this same minute
        same = []
        if name == "BTC" and _side_now is not None:
            try:
                m1 = _bt.minute_candles()
                if m1:
                    for r in sorted((r for r in rs if r["diff"] <= TARGET_RECENT_PCT and r.get("open")), key=lambda r: -r["ts"]):
                        c = m1.get(int(r["open"]) // 60 * 60 + _el_min * 60)
                        if c and (c[3] >= r["strike"]) == _side_now:
                            same.append(r)
                            if len(same) >= MINI_CALL_N:
                                break
            except Exception as _se:
                print(f"[target history] same-spot: {_se!r}")
        if len(same) >= 5:
            su = sum(1 for r in same if r["up"])
            sd_ = len(same) - su
            if su == sd_:                          # split -> the newest 5 decide
                _u5 = sum(1 for r in same[:5] if r["up"])
                sw = "UP" if _u5 > 5 - _u5 else "DOWN"
            else:
                sw = "UP" if su > sd_ else "DOWN"
            mini += (f'<div class="mc-same">Price is <b>{"ABOVE" if _side_now else "BELOW"}</b> the line {_el_min} min into the round - '
                     f'the last {len(same)} near rounds like that ended <b class="{"flat" if sw == "SPLIT" else sw.lower() if sw == "UP" else "down"}">'
                     f'{sw} {max(su, sd_)}/{len(same)} ({max(su, sd_) / len(same) * 100:.0f}%)</b></div>')
    try:
        _hc = history_check(name, _sp, line, d.get("elapsed_seconds"))
    except Exception:
        _hc = None
    if _hc:
        _w = "UP" if _hc["call"] == "YES" else "DOWN"
        _hcl = (f'<div class="mini-call hist-check mc-{"up" if _hc["call"] == "YES" else "down"}"><span class="mc-lbl">HISTORY CHECK</span>'
                f'<b class="mc-dir">{"<i class=va-u></i>" if _hc["call"] == "YES" else "<i class=va-d></i>"} {_w}</b><span class="mc-pct">{_hc["pct"] * 100:.0f}%</span>'
                f'<span class="mc-sub">Price is {abs(_hc["dist"]) * 100:.3f}% {"above" if _hc["dist"] >= 0 else "below"} the line {_hc["minute"]} min into the round. '
                f'Of {_hc["n"]:,} rounds in the last 30 days that were in this same spot, {_hc["pct"] * 100:.0f}% ended {_w}.</span></div>')
    # 2026-10-22: the old at-the-open box is retired on BOTH coins - only the 1:00 mini call (+ the BTC history check) show
    mini = ''                       # 2026-10-22 (user): no history check - only the mini call shows
    _TGT_MINI[name] = mini
    rows = '<div class="th-chips">'
    for r in near:
        h = r["h"] or {}
        sc, ok = h.get("sealed_call"), h.get("sealed_correct")
        when = dt.datetime.fromtimestamp(r["ts"], et)
        off = abs(r["strike"] - line)
        tip = (f'{when:%b %d %-I:%M %p} - target {fmt_price(r["strike"], dec)} '
               f'({"exact match" if off < 10 ** -dec else f"{r["diff"] * 100:.2f}% off"}) - ended {"UP" if r["up"] else "DOWN"}'
               + (f' - BRAIN called {"UP" if sc == "YES" else "DOWN"} ({"right" if ok else "wrong"})' if sc else ""))
        rows += (f'<span class="th-chip {"up" if r["up"] else "down"}" title="{_html_attr(tip)}">'
                 f'{"<i class=va-u></i>" if r["up"] else "<i class=va-d></i>"} {when:%b %-d %-I:%M%p}'.replace("AM", "a").replace("PM", "p") + '</span>')
    rows += '</div>' if near else ""
    if not near:
        rows = ""
    touch = ""
    try:
        for ts, tf, exact, px, mv in _target_touches(name, line):
            when = dt.datetime.fromtimestamp(ts, et)
            lab = {"1m": "1-min", "1h": "hourly", "1d": "daily"}[tf]
            if exact:
                touch = (f'<div class="th-row"><b>On the chart:</b> price last traded at {fmt_price(line, dec)} on '
                         f'{when:%b %d %-I:%M %p} <span class="hint">({lab} candle)</span>'
                         + (f' &rarr; <b class="{"up" if mv >= 0 else "down"}">{"up" if mv >= 0 else "down"} {abs(mv) * 100:.2f}%</b> '
                            f'<span class="hint">{"15 min" if tf == "1m" else ("1 hour" if tf == "1h" else "1 day")} later</span>' if mv is not None else "")
                         + '</div>')
                break
            touch = (f'<div class="th-row"><b>On the chart:</b> closest was {fmt_price(px, dec)} on {when:%b %d %-I:%M %p} '
                     f'<span class="hint">({lab} candle, {abs(px - line) / line * 100:.2f}% away)</span></div>')
    except Exception as _te:
        print(f"[target history] chart search: {_te!r}")
    if not rows and not touch:
        html = (f'<div class="tgt-hist"><div class="th-h">Past rounds near {fmt_price(line, dec)}</div>'
                f'<div class="hint">No past rounds near this target yet.</div></div>')
        _TGT_BODY[name] = '<div class="hint">No past rounds near this target yet.</div>'
    else:
        html = (f'<div class="tgt-hist"><div class="th-h">Last {len(recent)} rounds near {fmt_price(line, dec)} '
                f'<span class="hint">30 days</span></div>{mini}{rows}{touch}</div>')
        _TGT_BODY[name] = (f'{mini}<div class="bhb-sub">Last {len(recent)} rounds near {fmt_price(line, dec)} '
                           f'<span class="hint">(last 30 days &middot; hover a chip for details)</span></div>{rows}{touch}')
    _tgt_cache[ck] = (time.time(), html, _TGT_BODY.get(name, ""))
    if len(_tgt_cache) > 50:
        _tgt_cache.clear()
    return html


