            qs = urllib.parse.parse_qs(parsed.query)
            asset_name = (qs.get("asset") or [""])[0]
            try:
                minutes = max(1, min(180, int((qs.get("tf") or ["30"])[0])))
            except ValueError:
                minutes = 30
            asset_cfg = next((a for a in DASHBOARD_ASSETS if a["name"] == asset_name), None)
